/* ============================================================
   IRONFANG — stylized hunting action UI
   ============================================================ */
:root{
  --bg:#08110f;
  --deep:#050b0a;
  --panel:rgba(13,26,23,.80);
  --panel-solid:#0d1a17;
  --line:rgba(214,235,225,.14);
  --line-strong:rgba(232,180,90,.38);
  --text:#f4f1e6;
  --muted:#9fb0a9;
  --gold:#e8b45a;
  --gold-hi:#ffd98a;
  --teal:#6fd6c2;
  --red:#e2564a;
  --blue:#79b8ff;
  --violet:#b28bff;
  --font-title:"Palatino Linotype","Book Antiqua",Palatino,Georgia,serif;
  --font-body:"Avenir Next","Segoe UI",system-ui,-apple-system,Roboto,sans-serif;
  --safe-b:env(safe-area-inset-bottom,0px);
  --safe-l:env(safe-area-inset-left,0px);
  --safe-r:env(safe-area-inset-right,0px);
  --act:clamp(62px,11.4vmin,92px);
}
*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}
html,body{margin:0;height:100%;overflow:hidden;background:var(--deep);color:var(--text);font-family:var(--font-body)}
body{overscroll-behavior:none;user-select:none;-webkit-user-select:none}
#app{position:fixed;inset:0;overflow:hidden}
#scene{position:absolute;inset:0;width:100%;height:100%;display:block;outline:none;touch-action:none}
#vignette{position:absolute;inset:0;pointer-events:none;background:
  radial-gradient(ellipse at 50% 45%,transparent 46%,rgba(3,8,7,.34) 100%),
  linear-gradient(to bottom,rgba(3,7,6,.22),transparent 24%,transparent 74%,rgba(3,7,6,.38));
  z-index:2}
#ui{position:absolute;inset:0;z-index:3;pointer-events:none}
.hidden{display:none!important}
.muted{color:var(--muted)}
.small{font-size:12px;line-height:1.55}

/* ============ shared atoms ============ */
.btn{
  pointer-events:auto;cursor:pointer;border:1px solid var(--line);background:rgba(20,34,30,.72);
  color:var(--text);font-family:var(--font-body);font-weight:700;font-size:12px;letter-spacing:.16em;
  padding:14px 24px;border-radius:9px;transition:transform .14s ease,background .18s,border-color .18s,box-shadow .18s;
  text-transform:uppercase;position:relative;backdrop-filter:blur(8px)
}
.btn:hover{transform:translateY(-2px);border-color:rgba(232,180,90,.55);background:rgba(28,46,40,.9)}
.btn:active{transform:translateY(0) scale(.98)}
.btn.primary{background:linear-gradient(160deg,#f0c169,#c98f36);border-color:#f7d38e;color:#20160a;box-shadow:0 8px 26px rgba(232,180,90,.22),inset 0 1px 0 rgba(255,255,255,.4)}
.btn.primary:hover{background:linear-gradient(160deg,#ffd98a,#d99c3d);box-shadow:0 10px 34px rgba(232,180,90,.36)}
.btn.ghost{background:rgba(16,30,26,.6)}
.btn.danger{border-color:rgba(226,86,74,.5);color:#ffb4ab;background:rgba(60,20,18,.4)}
.btn.big{padding:18px 42px;font-size:14px;letter-spacing:.22em}
.btn[disabled]{opacity:.38;cursor:not-allowed;transform:none!important;box-shadow:none}
.glass{background:var(--panel);border:1px solid var(--line);border-radius:16px;backdrop-filter:blur(16px);box-shadow:0 22px 60px rgba(0,0,0,.35),inset 0 1px 0 rgba(255,255,255,.04)}
.card-eyebrow{font-size:9px;letter-spacing:.28em;color:var(--gold);font-weight:800;text-transform:uppercase}
.material-pill{pointer-events:auto;font-size:11px;color:var(--gold-hi);border:1px solid var(--line-strong);background:rgba(232,180,90,.07);padding:7px 12px;border-radius:999px;letter-spacing:.08em}
kbd{font-family:var(--font-body);font-size:10px;background:rgba(255,255,255,.08);border:1px solid var(--line);border-bottom-width:2px;border-radius:4px;padding:2px 5px;color:#dfe8e3}

/* ============ screens ============ */
.screen{position:absolute;inset:0;pointer-events:auto;display:flex;flex-direction:column}
.title-screen{
  justify-content:center;padding:clamp(24px,6vw,90px);
  background:
    radial-gradient(ellipse at 22% 55%,rgba(5,11,10,.15),rgba(5,11,10,.72) 62%,rgba(5,11,10,.92) 100%),
    linear-gradient(90deg,rgba(4,10,9,.82) 0%,rgba(4,10,9,.42) 46%,transparent 78%);
}
.title-wrap{max-width:640px;pointer-events:auto}
.crest{width:46px;height:46px;margin-bottom:18px;opacity:.9}
.crest svg{width:100%;height:100%;fill:var(--gold);filter:drop-shadow(0 0 18px rgba(232,180,90,.45))}
.logo{
  font-family:var(--font-title);font-weight:400;font-size:clamp(62px,11vw,132px);line-height:.82;
  letter-spacing:.02em;margin:0 0 10px;color:#f8f3e6;text-shadow:0 14px 48px rgba(0,0,0,.6)
}
.logo span{color:var(--gold);font-style:italic}
.tagline{font-size:11px;letter-spacing:.52em;color:var(--gold);margin:0 0 26px;font-weight:700}
.blurb{color:#c7d2cc;font-size:14px;line-height:1.7;max-width:470px;margin:0 0 34px;text-shadow:0 2px 12px rgba(0,0,0,.5)}
.title-actions{display:flex;gap:12px;flex-wrap:wrap;align-items:center}
.hint-line{font-size:11px;letter-spacing:.12em;color:#8fa39b;margin-top:22px}
.title-footer{position:absolute;left:clamp(24px,6vw,90px);right:clamp(24px,6vw,90px);bottom:22px;display:flex;justify-content:space-between;font-size:9px;letter-spacing:.24em;color:#6e837b}
.desk-only{display:inline}

/* ============ hub ============ */
.hub-screen{padding:clamp(16px,3vw,34px);background:linear-gradient(100deg,rgba(5,11,10,.82) 0%,rgba(5,11,10,.38) 48%,rgba(5,11,10,.12) 100%)}
.hub-top{display:flex;justify-content:space-between;align-items:center;pointer-events:auto}
.brand{font-family:var(--font-title);letter-spacing:.18em;font-size:15px;color:#f4efe2}
.brand.small{font-size:13px;letter-spacing:.24em}
.brand-mark{color:var(--gold);margin-right:6px}
.hub-stats{display:flex;gap:10px;flex-wrap:wrap;justify-content:flex-end}
.stat-chip{display:flex;align-items:center;gap:8px;background:rgba(10,20,17,.62);border:1px solid var(--line);border-radius:999px;padding:7px 13px;font-size:10px;letter-spacing:.13em;color:#c6d3cd;backdrop-filter:blur(10px)}
.stat-chip b{color:var(--gold-hi);font-size:12px}
.hub-main{flex:1;display:flex;align-items:center;justify-content:space-between;gap:clamp(20px,5vw,80px);padding:20px 0 10px;pointer-events:none}
.hunter-card{width:min(320px,34vw);padding:24px;pointer-events:auto}
.weapon-showcase{height:92px;display:flex;align-items:center;justify-content:center;margin:8px 0 4px;filter:drop-shadow(0 8px 24px rgba(232,180,90,.22))}
.weapon-showcase svg{width:96px;height:96px;stroke:var(--gold);fill:none;stroke-width:1.3;stroke-linecap:round;stroke-linejoin:round;opacity:.95}
.hunter-card h2{font-family:var(--font-title);font-weight:400;font-size:29px;margin:2px 0 8px;letter-spacing:.01em}
.weapon-desc{color:var(--muted);font-size:12px;line-height:1.6;margin:0 0 18px;min-height:38px}
.mini-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:16px}
.mini-stat{background:rgba(255,255,255,.03);border:1px solid var(--line);border-radius:8px;padding:8px 6px;text-align:center}
.mini-stat span{display:block;font-size:8px;letter-spacing:.18em;color:#83988f;margin-bottom:4px}
.mini-stat b{font-size:15px;color:#f0ebdd;font-family:var(--font-title);font-weight:400}
.weapon-switch{display:flex;gap:7px;margin-bottom:12px}
.wsw{flex:1;cursor:pointer;background:rgba(255,255,255,.03);border:1px solid var(--line);border-radius:8px;padding:9px 4px;color:#a9bbb4;font-size:9px;letter-spacing:.07em;font-weight:700;transition:.16s;font-family:var(--font-body)}
.wsw:hover{background:rgba(255,255,255,.06);color:#fff}
.wsw.on{border-color:var(--gold);color:var(--gold-hi);background:rgba(232,180,90,.1);box-shadow:0 0 18px rgba(232,180,90,.1)}
.skin-line{font-size:10px;letter-spacing:.1em;color:#8ea29a;border-top:1px solid var(--line);padding-top:11px;display:flex;justify-content:space-between;gap:8px}
.skin-line b{color:var(--gold-hi);font-weight:700}
.hub-menu{width:min(440px,42vw);pointer-events:auto}
.hub-tag{font-size:9px;letter-spacing:.32em;color:var(--gold);margin-bottom:14px}
.hub-title{font-family:var(--font-title);font-weight:400;font-size:clamp(32px,4.2vw,54px);line-height:1.02;margin:0 0 26px;text-shadow:0 8px 30px rgba(0,0,0,.5)}
.menu-btn{
  width:100%;display:flex;align-items:center;gap:15px;cursor:pointer;text-align:left;
  background:rgba(11,22,19,.64);border:1px solid var(--line);border-radius:12px;padding:14px 17px;margin-bottom:9px;
  color:var(--text);backdrop-filter:blur(12px);transition:.18s;position:relative;overflow:hidden;font-family:var(--font-body)
}
.menu-btn::before{content:"";position:absolute;left:0;top:0;bottom:0;width:2px;background:var(--gold);opacity:0;transition:.2s}
.menu-btn:hover{background:rgba(24,42,36,.86);transform:translateX(4px);border-color:rgba(232,180,90,.38)}
.menu-btn:hover::before{opacity:1}
.menu-btn.primary{border-color:rgba(232,180,90,.5);background:linear-gradient(110deg,rgba(232,180,90,.16),rgba(20,36,30,.7) 60%)}
.menu-btn.primary::before{opacity:1}
.mb-icon{width:38px;height:38px;border-radius:9px;background:rgba(232,180,90,.1);border:1px solid rgba(232,180,90,.2);display:flex;align-items:center;justify-content:center;flex:0 0 auto}
.mb-icon svg{width:19px;height:19px;stroke:var(--gold);fill:none;stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round}
.mb-text{flex:1;display:flex;flex-direction:column;gap:3px}
.mb-text b{font-size:14px;letter-spacing:.04em;font-weight:700}
.mb-text small{font-size:10px;color:#8fa39b;letter-spacing:.04em}
.mb-arrow{font-family:var(--font-title);font-size:24px;color:var(--gold);opacity:.55}
.hub-note{font-size:10px;color:#7e9189;letter-spacing:.08em;margin-top:14px;padding-left:3px}
.hub-footer{display:flex;justify-content:space-between;gap:16px;font-size:10px;color:#81978e;letter-spacing:.04em;align-items:center}
.touch-note{display:none}
@media (pointer:coarse){.ctrl-hint{display:none}.touch-note{display:block}}

/* ============ panel screens ============ */
.panel-screen{padding:clamp(16px,3.4vw,40px);background:linear-gradient(180deg,rgba(5,12,10,.93),rgba(6,14,12,.86) 40%,rgba(5,12,10,.95));overflow-y:auto;gap:18px}
.panel-head{display:flex;align-items:center;gap:20px;max-width:1180px;width:100%;margin:0 auto;flex-wrap:wrap}
.panel-head h2{font-family:var(--font-title);font-weight:400;font-size:clamp(30px,4vw,44px);margin:3px 0 0;line-height:1}
.panel-head .material-pill{margin-left:auto}
.back-btn{cursor:pointer;background:rgba(255,255,255,.04);border:1px solid var(--line);color:#d7e1db;border-radius:9px;padding:11px 15px;font-size:12px;font-family:var(--font-body);letter-spacing:.12em;transition:.16s;display:flex;align-items:center;gap:4px}
.back-btn:hover{border-color:var(--line-strong);background:rgba(232,180,90,.08);color:var(--gold-hi)}
.back-btn span{font-size:10px;letter-spacing:.18em}
.panel-foot{max-width:1180px;width:100%;margin:auto auto 0;padding-top:10px;display:flex;justify-content:space-between;align-items:center;gap:16px;font-size:11px;flex-wrap:wrap}
.loadout-strip{display:flex;gap:6px;align-items:center;font-size:10px;letter-spacing:.1em;color:#a9bbb4}

/* ============ quest board ============ */
.quest-grid{max-width:1180px;width:100%;margin:0 auto;display:grid;grid-template-columns:repeat(3,1fr);gap:16px}
.quest-card{position:relative;border-radius:16px;overflow:hidden;border:1px solid var(--line);background:rgba(13,26,23,.82);cursor:pointer;transition:.2s;display:flex;flex-direction:column;pointer-events:auto;min-height:340px;backdrop-filter:blur(8px)}
.quest-card:hover{transform:translateY(-4px);border-color:rgba(232,180,90,.5);box-shadow:0 24px 50px rgba(0,0,0,.45)}
.q-art{height:132px;position:relative;overflow:hidden;display:flex;align-items:center;justify-content:center}
.q-art::after{content:"";position:absolute;inset:0;background:linear-gradient(to top,rgba(13,26,23,.95),transparent 70%)}
.q-art svg{width:84%;height:84%;opacity:.9;filter:drop-shadow(0 8px 22px rgba(0,0,0,.4))}
.q-rank{position:absolute;top:12px;left:12px;z-index:2;font-size:8px;letter-spacing:.2em;background:rgba(0,0,0,.45);border:1px solid rgba(255,255,255,.2);border-radius:999px;padding:5px 9px;color:#fff;font-weight:800}
.q-body{padding:16px 18px 18px;display:flex;flex-direction:column;flex:1;position:relative;z-index:2}
.q-body h3{font-family:var(--font-title);font-weight:400;font-size:22px;margin:0 0 3px}
.q-sub{font-size:10px;color:var(--gold);letter-spacing:.14em;font-weight:700;margin-bottom:12px}
.q-meta{display:flex;gap:14px;font-size:10px;color:#9db0a7;letter-spacing:.05em;margin-bottom:14px;flex-wrap:wrap}
.q-meta span{display:flex;align-items:center;gap:4px}
.q-desc{font-size:11px;line-height:1.55;color:#93a79f;margin:0 0 14px;flex:1}
.q-rewards{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:14px}
.mat-chip{font-size:9px;letter-spacing:.06em;border-radius:5px;padding:4px 7px;border:1px solid var(--line);color:#c9d7d1;background:rgba(255,255,255,.03);display:flex;align-items:center;gap:5px}
.mat-dot{width:6px;height:6px;border-radius:50%;display:inline-block}
.q-launch{display:flex;justify-content:space-between;align-items:center;border-top:1px solid var(--line);padding-top:13px;margin-top:auto}
.q-launch span{font-size:10px;letter-spacing:.16em;color:#8b9f97}
.q-launch b{font-family:var(--font-title);font-size:13px;color:var(--gold-hi);letter-spacing:.1em;font-weight:400}
.q-arrow{width:32px;height:32px;border-radius:50%;background:rgba(232,180,90,.13);border:1px solid rgba(232,180,90,.4);display:flex;align-items:center;justify-content:center;color:var(--gold-hi);font-size:16px;transition:.18s}
.quest-card:hover .q-arrow{background:var(--gold);color:#1a1207}
.quest-card.cleared{border-color:rgba(111,214,194,.26)}
.q-cleared{position:absolute;top:12px;right:12px;z-index:2;font-size:8px;letter-spacing:.16em;color:#9ff1e2;border:1px solid rgba(111,214,194,.4);background:rgba(13,40,35,.7);padding:5px 8px;border-radius:999px;font-weight:800}

/* ============ blacksmith ============ */
.smith-layout{max-width:1180px;width:100%;margin:0 auto;display:grid;grid-template-columns:230px minmax(0,1fr) 250px;gap:16px;align-items:stretch}
.smith-weapons{padding:14px;display:flex;flex-direction:column;gap:8px}
.smith-w{display:flex;align-items:center;gap:10px;padding:10px;border-radius:9px;border:1px solid transparent;background:rgba(255,255,255,.025);cursor:pointer;transition:.16s;color:#b9c9c2;font-size:11px;font-weight:600;letter-spacing:.06em;text-align:left;font-family:var(--font-body)}
.smith-w:hover{background:rgba(255,255,255,.06)}
.smith-w.on{border-color:rgba(232,180,90,.4);background:rgba(232,180,90,.09);color:var(--gold-hi)}
.smith-w .wicon{width:34px;height:34px;flex:0 0 auto;display:flex;align-items:center;justify-content:center;border-radius:7px;background:rgba(0,0,0,.25)}
.smith-w .wicon svg{width:24px;height:24px;stroke:currentColor;fill:none;stroke-width:1.4;stroke-linecap:round;stroke-linejoin:round}
.smith-w small{display:block;font-size:9px;color:#82968e;letter-spacing:.08em;font-weight:400;margin-top:2px}
.smith-w.on small{color:rgba(255,217,138,.7)}
.smith-detail{padding:24px;display:flex;flex-direction:column;min-height:380px}
.sd-head{display:flex;gap:20px;align-items:center;margin-bottom:18px;flex-wrap:wrap}
.sd-art{width:130px;height:110px;flex:0 0 auto;display:flex;align-items:center;justify-content:center;background:radial-gradient(ellipse at center,rgba(232,180,90,.12),transparent 70%);border-radius:12px}
.sd-art svg{width:100px;height:100px;stroke:var(--gold);fill:none;stroke-width:1.2;stroke-linecap:round;stroke-linejoin:round;filter:drop-shadow(0 6px 16px rgba(232,180,90,.24))}
.sd-title h3{font-family:var(--font-title);font-weight:400;font-size:30px;margin:0 0 4px}
.sd-title p{margin:0;color:#90a49c;font-size:11px;line-height:1.55;max-width:340px}
.sd-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin-bottom:20px}
.sd-stat{background:rgba(0,0,0,.18);border:1px solid var(--line);border-radius:9px;padding:10px 12px}
.sd-stat span{display:block;font-size:8px;letter-spacing:.16em;color:#81958d;margin-bottom:5px}
.sd-stat b{font-family:var(--font-title);font-weight:400;font-size:19px;color:#f2ecdf}
.sd-stat b em{font-style:normal;font-size:11px;color:#8fd8c9;margin-left:4px}
.upgrade-row{display:flex;gap:14px;align-items:center;justify-content:space-between;padding:14px 0;border-top:1px solid var(--line);flex-wrap:wrap}
.cost-chip{display:inline-flex;align-items:center;gap:6px;font-size:10px;border:1px solid var(--line);border-radius:6px;padding:6px 9px;color:#c8d7d0;background:rgba(255,255,255,.02);margin-right:6px}
.cost-chip.lacking{color:#ff9a90;border-color:rgba(226,86,74,.32)}
.upgrade-title{font-family:var(--font-title);font-size:18px;margin:0 0 6px;font-weight:400}
.upgrade-sub{font-size:10px;color:#84988f;letter-spacing:.03em;margin:0 0 9px}
.skins{margin-top:auto;padding-top:12px;border-top:1px solid var(--line)}
.skins h4{margin:0 0 10px;font-size:9px;letter-spacing:.22em;color:var(--gold);font-weight:800}
.skin-grid{display:flex;gap:9px;flex-wrap:wrap}
.skin-card{position:relative;cursor:pointer;border:1px solid var(--line);border-radius:9px;padding:8px 10px;background:rgba(255,255,255,.025);min-width:86px;transition:.16s;font-family:var(--font-body);color:#bdcbc5;font-size:9px;letter-spacing:.05em;text-align:left}
.skin-card:hover{border-color:rgba(232,180,90,.4)}
.skin-card.on{border-color:var(--gold);background:rgba(232,180,90,.1);color:var(--gold-hi)}
.skin-card.locked{opacity:.62}
.skin-swatch{display:block;width:100%;height:17px;border-radius:5px;margin-bottom:6px;border:1px solid rgba(255,255,255,.14)}
.skin-card small{display:block;font-size:8px;color:#81958d;margin-top:2px;letter-spacing:.06em}
.skin-card.on small{color:rgba(255,217,138,.7)}
.smith-inventory{padding:18px}
.smith-inventory h3{font-family:var(--font-title);font-weight:400;font-size:19px;margin:0 0 14px}
.inv-row{display:flex;align-items:center;gap:9px;padding:8px 0;border-bottom:1px dashed rgba(255,255,255,.06);font-size:10px;color:#b4c4bd}
.inv-row:last-child{border:0}
.inv-row .mat-dot{width:8px;height:8px}
.inv-row span{flex:1;letter-spacing:.02em}
.inv-row b{color:#f0ead9;font-size:12px;font-family:var(--font-title);font-weight:400}
.inv-empty{font-size:10px;color:#7d9189;line-height:1.7;padding:8px 0}

/* ============ settings ============ */
.settings-wrap{max-width:1000px;width:100%;margin:0 auto;display:grid;grid-template-columns:repeat(2,1fr);gap:16px}
.settings-card{padding:22px}
.settings-card h3{font-family:var(--font-title);font-weight:400;font-size:21px;margin:0 0 18px}
.slider-row{display:grid;grid-template-columns:1fr 130px 34px;align-items:center;gap:12px;padding:9px 0;font-size:11px;color:#bccbc5;letter-spacing:.04em}
.slider-row b{text-align:right;font-size:11px;color:var(--gold-hi);font-weight:600}
input[type=range]{-webkit-appearance:none;appearance:none;height:4px;border-radius:4px;background:rgba(255,255,255,.15);outline:none;cursor:pointer;width:100%}
input[type=range]::-webkit-slider-thumb{-webkit-appearance:none;width:16px;height:16px;border-radius:50%;background:var(--gold);border:2px solid #2b1f10;box-shadow:0 0 12px rgba(232,180,90,.5)}
input[type=range]::-moz-range-thumb{width:14px;height:14px;border:none;border-radius:50%;background:var(--gold)}
.toggle-row{display:flex;align-items:center;gap:14px;padding:13px 0;border-top:1px solid var(--line);cursor:pointer;font-size:11px;color:#c6d3cd}
.toggle-row span b{display:block;font-size:11px;letter-spacing:.02em;font-weight:600}
.toggle-row span small{display:block;font-size:9px;color:#82968e;margin-top:3px;letter-spacing:.03em}
.toggle-row input{display:none}
.toggle{position:relative;flex:0 0 auto;width:38px;height:21px;border-radius:999px;background:rgba(255,255,255,.12);border:1px solid var(--line);transition:.2s;margin-left:auto}
.toggle::after{content:"";position:absolute;top:2px;left:2px;width:15px;height:15px;border-radius:50%;background:#8fa39b;transition:.2s}
.toggle-row input:checked + .toggle{background:rgba(232,180,90,.32);border-color:rgba(232,180,90,.6)}
.toggle-row input:checked + .toggle::after{left:19px;background:var(--gold-hi)}

/* ============ result ============ */
.result-screen{align-items:center;justify-content:center;background:radial-gradient(ellipse at 50% 40%,rgba(5,12,10,.55),rgba(4,9,8,.93));padding:18px;overflow-y:auto}
.result-card{width:min(560px,94vw);padding:clamp(22px,4vw,38px);text-align:center;position:relative;overflow:hidden;max-height:94vh;overflow-y:auto}
.result-card::before{content:"";position:absolute;top:0;left:0;right:0;height:3px;background:linear-gradient(90deg,transparent,var(--gold),transparent)}
.result-crest{width:58px;height:58px;margin:0 auto 12px}
.result-crest svg{width:100%;height:100%;fill:var(--gold);filter:drop-shadow(0 0 20px rgba(232,180,90,.45))}
.result-crest.defeat svg{fill:#7c8a85;filter:none}
.result-screen h2{font-family:var(--font-title);font-weight:400;font-size:clamp(38px,6vw,58px);margin:6px 0 2px;line-height:1}
.result-screen .card-eyebrow{color:#cbd8d2}
.result-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:24px 0 18px}
.rs{background:rgba(255,255,255,.03);border:1px solid var(--line);border-radius:9px;padding:10px 4px}
.rs span{display:block;font-size:8px;letter-spacing:.13em;color:#81958d;margin-bottom:5px}
.rs b{font-family:var(--font-title);font-weight:400;font-size:17px;color:#f0ebdd}
.reward-block{border-top:1px solid var(--line);padding-top:16px;text-align:left}
.reward-head{display:flex;justify-content:space-between;font-size:9px;letter-spacing:.2em;color:var(--gold);font-weight:800;margin-bottom:10px}
.reward-list{display:flex;flex-direction:column;gap:6px;max-height:180px;overflow-y:auto}
.reward-row{display:flex;align-items:center;gap:9px;background:rgba(255,255,255,.025);border:1px solid rgba(255,255,255,.06);border-radius:7px;padding:8px 10px;font-size:11px;color:#cdd9d3}
.reward-row b{margin-left:auto;font-size:12px;color:var(--gold-hi)}
.reward-row .tag{font-size:8px;letter-spacing:.1em;color:#8de7d6;border:1px solid rgba(111,214,194,.3);border-radius:4px;padding:2px 5px}
.part-note{font-size:10px;color:#8ea29a;margin-top:9px;line-height:1.6}
.result-actions{display:flex;gap:10px;justify-content:center;margin-top:22px;flex-wrap:wrap}
.result-actions .btn{flex:1;min-width:150px;padding:15px 18px;font-size:11px}

/* ============ HUD ============ */
#hunt-ui{position:absolute;inset:0;pointer-events:none}
.hud-player{position:absolute;top:calc(16px + env(safe-area-inset-top,0px));left:calc(18px + var(--safe-l));display:flex;gap:10px;align-items:flex-start}
.hud-portrait{width:46px;height:46px;border-radius:50%;border:1px solid rgba(232,180,90,.5);background:radial-gradient(circle at 40% 35%,#27423a,#0c1714);display:flex;align-items:center;justify-content:center;box-shadow:0 6px 18px rgba(0,0,0,.5)}
.hud-portrait svg{width:25px;height:25px;stroke:var(--gold);fill:none;stroke-width:1.4;stroke-linecap:round;stroke-linejoin:round}
.hud-bars{width:min(260px,36vw)}
.hud-name-row{display:flex;align-items:center;justify-content:space-between;margin-bottom:4px}
.hud-name{font-size:9px;letter-spacing:.24em;color:#d6e0db;font-weight:800;text-shadow:0 1px 4px #000}
.weapon-tag{font-size:8px;letter-spacing:.13em;color:var(--gold);border:1px solid rgba(232,180,90,.3);border-radius:3px;padding:2px 5px;background:rgba(0,0,0,.4)}
.bar{position:relative;height:13px;border-radius:3px;background:rgba(0,0,0,.55);border:1px solid rgba(255,255,255,.13);overflow:hidden;margin-bottom:5px}
.bar-fill{position:absolute;inset:0;transform-origin:left;transition:transform .18s ease-out;border-radius:2px}
.bar.hp .bar-fill{background:linear-gradient(180deg,#8fe36f,#4fa63f);box-shadow:0 0 12px rgba(110,220,90,.28)}
.bar.hp.low .bar-fill{background:linear-gradient(180deg,#ff8a6b,#c53a2d);animation:hpPulse 1s infinite}
.bar.stam{height:9px}
.bar.stam .bar-fill{background:linear-gradient(180deg,#7fd9c8,#2f8d7d);box-shadow:0 0 10px rgba(111,214,194,.22)}
.bar-label{position:absolute;right:5px;top:50%;transform:translateY(-50%);font-size:8px;font-weight:800;color:rgba(255,255,255,.85);text-shadow:0 1px 2px #000;letter-spacing:.06em}
.bar.hp .bar-chunks{position:absolute;inset:0;background:repeating-linear-gradient(90deg,transparent 0 19%,rgba(0,0,0,.28) 19% 20%);pointer-events:none;opacity:.6}
.hud-monster{position:absolute;top:calc(14px + env(safe-area-inset-top,0px));left:50%;transform:translateX(-50%);width:min(540px,44vw);text-align:center}
.monster-title-row{display:flex;align-items:center;justify-content:center;gap:8px;margin-bottom:5px}
.monster-icon{display:flex}
.monster-icon svg{width:15px;height:15px;stroke:#f0d8aa;fill:none;stroke-width:1.5;stroke-linecap:round}
.hud-monster h3{font-family:var(--font-title);font-weight:400;font-size:clamp(14px,1.8vw,20px);letter-spacing:.1em;margin:0;color:#f6efe0;text-shadow:0 2px 8px rgba(0,0,0,.7);text-transform:uppercase}
.phase-tag{font-size:7px;letter-spacing:.15em;padding:2px 5px;border-radius:3px;border:1px solid rgba(255,255,255,.22);color:#c0cfc8;font-weight:800}
.phase-tag.enraged{color:#ff9b6c;border-color:rgba(255,120,60,.6);background:rgba(80,20,10,.5);animation:enragePulse 1.4s infinite}
.phase-tag.tired{color:#9ec6ff;border-color:rgba(120,170,255,.45);background:rgba(12,30,60,.5)}
.monster-bar{height:12px;background:rgba(0,0,0,.62);border:1px solid rgba(232,180,90,.32);border-radius:3px;overflow:hidden;position:relative;box-shadow:0 4px 18px rgba(0,0,0,.45)}
.monster-fill{position:absolute;inset:0;background:linear-gradient(180deg,#f0a35f,#b0442c);transform-origin:left;transition:transform .2s ease-out}
.monster-bar .monster-ticks{position:absolute;inset:0;background:repeating-linear-gradient(90deg,transparent 0 9.8%,rgba(0,0,0,.35) 9.8% 10%);pointer-events:none}
.part-chips{display:flex;gap:5px;justify-content:center;margin-top:6px;flex-wrap:wrap}
.part-chip{font-size:7px;letter-spacing:.11em;border:1px solid rgba(255,255,255,.18);border-radius:3px;padding:2px 5px;color:rgba(255,255,255,.6);background:rgba(0,0,0,.32);transition:.2s;font-weight:700}
.part-chip.broken{color:#171006;background:var(--gold);border-color:var(--gold-hi);box-shadow:0 0 10px rgba(232,180,90,.45)}
.part-chip.weak{border-color:rgba(255,200,120,.4);color:#ffcf87}
.hud-quest{position:absolute;top:calc(16px + env(safe-area-inset-top,0px));right:calc(18px + var(--safe-r));display:flex;flex-direction:column;align-items:flex-end;gap:4px}
.timer{display:flex;align-items:center;gap:6px;background:rgba(5,12,10,.55);border:1px solid var(--line);border-radius:7px;padding:5px 9px;backdrop-filter:blur(6px)}
.timer-icon{color:var(--gold);font-size:13px;line-height:1}
.timer b{font-family:var(--font-title);font-weight:400;font-size:16px;letter-spacing:.06em;color:#f4efe2}
.timer.low b{color:#ff8a72;animation:hpPulse .9s infinite}
.quest-label{font-size:8px;letter-spacing:.2em;color:#b9c8c1;text-shadow:0 1px 4px #000;text-transform:uppercase;max-width:160px;text-align:right}
.pause-btn{pointer-events:auto;margin-top:4px;width:28px;height:24px;border-radius:6px;border:1px solid var(--line);background:rgba(5,12,10,.5);color:#c6d3cd;font-size:10px;letter-spacing:.1em;cursor:pointer;backdrop-filter:blur(6px)}
.pause-btn:hover{border-color:var(--gold);color:var(--gold-hi)}
.hud-lock{position:absolute;left:50%;bottom:100px;transform:translateX(-50%);font-size:8px;letter-spacing:.22em;color:var(--gold);display:flex;align-items:center;gap:7px;text-shadow:0 1px 4px #000;opacity:.9}
.hud-lock span{width:6px;height:6px;border-radius:50%;background:var(--gold);box-shadow:0 0 8px var(--gold)}
.combo-meter{position:absolute;left:50%;bottom:calc(24px + var(--safe-b));transform:translateX(-50%);display:flex;align-items:center;gap:8px;opacity:0;transition:opacity .2s}
.combo-meter.on{opacity:1}
.combo-label{font-size:8px;letter-spacing:.24em;color:var(--gold);font-weight:800}
.combo-meter .pips{display:flex;gap:4px}
.combo-meter .pips i{width:22px;height:4px;background:rgba(255,255,255,.14);border-radius:2px;transition:.15s}
.combo-meter .pips i.on{background:var(--gold);box-shadow:0 0 8px rgba(232,180,90,.55)}
.item-readout{position:absolute;left:calc(18px + var(--safe-l));bottom:calc(168px + var(--safe-b));display:flex;align-items:center;gap:7px;font-size:8px;letter-spacing:.14em;color:#c5d3cc;text-shadow:0 1px 4px #000;opacity:.9}
.item-readout b{color:var(--gold-hi);font-size:11px}
.item-icon{width:19px;height:19px;display:flex;border:1px solid rgba(232,180,90,.3);border-radius:4px;background:rgba(0,0,0,.35);align-items:center;justify-content:center}
.item-icon svg{width:12px;height:12px;stroke:var(--gold);fill:none;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round}
.announce{position:absolute;left:50%;top:32%;transform:translate(-50%,-50%);text-align:center;font-family:var(--font-title);font-size:clamp(24px,4vw,42px);letter-spacing:.16em;color:#f6e6c0;text-shadow:0 4px 30px rgba(0,0,0,.8),0 0 50px rgba(232,180,90,.25);opacity:0;pointer-events:none;transition:opacity .3s,transform .3s;white-space:nowrap}
.announce.show{opacity:1;transform:translate(-50%,-50%) scale(1.04)}
.announce.enraged{color:#ffb08a}
.announce.tired{color:#a9c8ff}
.subtitle{position:absolute;left:50%;bottom:138px;transform:translateX(-50%);font-size:11px;letter-spacing:.08em;color:#e8dfc9;text-shadow:0 2px 6px #000;background:rgba(4,10,8,.45);padding:5px 12px;border-radius:5px;opacity:0;transition:opacity .25s;max-width:80vw;text-align:center}
.subtitle.show{opacity:1}
.charge-indicator{position:absolute;left:50%;bottom:calc(88px + var(--safe-b));transform:translateX(-50%);text-align:center;font-size:9px;letter-spacing:.2em;color:var(--gold-hi);text-shadow:0 2px 6px #000}
.charge-indicator b{font-weight:700}
.charge-pips{display:flex;gap:4px;margin-top:5px;justify-content:center}
.charge-pips i{width:26px;height:3px;border-radius:2px;background:rgba(255,255,255,.2)}
.charge-pips i.on{background:var(--gold-hi);box-shadow:0 0 8px var(--gold)}
.action-hint{position:absolute;left:50%;bottom:calc(64px + var(--safe-b));transform:translateX(-50%);font-size:9px;letter-spacing:.13em;color:rgba(230,240,235,.7);text-shadow:0 1px 4px #000;opacity:0;transition:opacity .2s;white-space:nowrap}
.action-hint.show{opacity:1}
.camera-hint{position:absolute;right:calc(18px + var(--safe-r));bottom:calc(26px + var(--safe-b));font-size:9px;letter-spacing:.08em;color:rgba(220,232,227,.65);text-shadow:0 1px 3px #000;opacity:0;transition:opacity .4s;text-align:right}
.camera-hint.show{opacity:1}
.camera-hint kbd{font-size:9px}

/* ============ touch controls ============ */
.touch-controls{position:absolute;inset:0;pointer-events:none;z-index:5}
#stick-zone{position:absolute;left:calc(20px + var(--safe-l));bottom:calc(22px + var(--safe-b));width:150px;height:170px;pointer-events:auto;display:flex;flex-direction:column;align-items:center;justify-content:flex-end}
#stick-base{width:clamp(104px,17vmin,138px);height:clamp(104px,17vmin,138px);border-radius:50%;border:1.5px solid rgba(230,240,235,.25);background:radial-gradient(circle at 50% 45%,rgba(20,38,33,.5),rgba(5,12,10,.32));position:relative;touch-action:none;box-shadow:inset 0 0 26px rgba(0,0,0,.35)}
#stick-base .stick-ring{position:absolute;inset:12px;border-radius:50%;border:1px dashed rgba(255,255,255,.1)}
#stick-knob{position:absolute;left:50%;top:50%;width:44%;height:44%;border-radius:50%;transform:translate(-50%,-50%);background:radial-gradient(circle at 38% 30%,rgba(240,250,246,.4),rgba(88,124,113,.6));border:1px solid rgba(255,255,255,.4);box-shadow:0 5px 18px rgba(0,0,0,.35);will-change:transform;transition:transform .04s}
.stick-label{font-size:7px;letter-spacing:.24em;color:rgba(220,232,227,.45);margin-top:7px;font-weight:700}
#action-cluster{position:absolute;right:calc(4px + var(--safe-r));bottom:calc(2px + var(--safe-b));width:270px;height:270px;pointer-events:none;transform-origin:bottom right}
.act-btn,.lock-btn{position:absolute;pointer-events:auto;border-radius:50%;border:1.5px solid rgba(240,248,244,.24);background:radial-gradient(circle at 38% 28%,rgba(42,68,60,.82),rgba(9,19,16,.86));color:#f0f5f2;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;touch-action:none;backdrop-filter:blur(4px);box-shadow:0 6px 20px rgba(0,0,0,.4),inset 0 1px 0 rgba(255,255,255,.14);transition:transform .07s,background .12s,border-color .12s;font-family:var(--font-body);padding:0}
.act-btn:active,.act-btn.pressed{transform:scale(.92);background:radial-gradient(circle at 38% 28%,rgba(232,180,90,.55),rgba(70,45,12,.85));border-color:rgba(255,217,138,.85)}
.act-icon{display:flex;align-items:center;justify-content:center}
.act-icon svg{width:clamp(20px,3.4vmin,30px);height:clamp(20px,3.4vmin,30px);stroke:#f3f8f5;fill:none;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round;filter:drop-shadow(0 1px 2px rgba(0,0,0,.5))}
.act-name{font-size:clamp(6px,0.9vmin,8px);letter-spacing:.12em;font-weight:800;color:rgba(236,245,241,.72)}
.btn-attack{right:10px;bottom:6px;width:calc(var(--act) + 8px);height:calc(var(--act) + 8px);border-color:rgba(232,180,90,.45);background:radial-gradient(circle at 38% 28%,rgba(66,87,58,.85),rgba(10,22,17,.9))}
.btn-attack .act-icon svg{width:clamp(26px,4.4vmin,38px);height:clamp(26px,4.4vmin,38px);stroke:var(--gold-hi);stroke-width:1.7}
