function weaponArt(id) { return WEAPON_ART[id] || ''; }

export class UI {
  constructor(game) {
    this.game = game;
    this.screen = 'title';
    this.smithWeapon = 'greatsword';
    this.huntEls = {
      root: document.getElementById('hunt-ui'),
      hpFill: document.getElementById('hp-fill'),
      hpText: document.getElementById('hp-text'),
      stamFill: document.getElementById('stam-fill'),
      stamText: document.getElementById('stam-text'),
      monsterName: document.getElementById('monster-name'),
      monsterPhase: document.getElementById('monster-phase'),
      monsterFill: document.getElementById('monster-fill'),
      partChips: document.getElementById('part-chips'),
      timerText: document.getElementById('timer-text'),
      timer: document.getElementById('timer'),
      questName: document.getElementById('hud-quest-name'),
      weaponTag: document.getElementById('hud-weapon-tag'),
      comboMeter: document.getElementById('combo-meter'),
      comboPips: [...document.querySelectorAll('.combo-meter .pips i')],
      itemCount: document.getElementById('item-count'),
      touchItemCount: document.getElementById('touch-item-count'),
      announce: document.getElementById('announce'),
      subtitle: document.getElementById('subtitle'),
      charge: document.getElementById('charge-indicator'),
      chargePips: [...document.querySelectorAll('.charge-pips i')],
      hint: document.getElementById('action-hint'),
      lock: document.getElementById('lock-indicator'),
      cameraHint: document.getElementById('camera-hint'),
      touch: document.getElementById('touch-controls'),
      touchLock: document.getElementById('touch-lock'),
      hp: document.querySelector('.bar.hp'),
    };
    this.damageLayer = document.getElementById('damage-layer');
    this.toastEl = document.getElementById('toast');
    this.flashEl = document.getElementById('flash');
    this.fadeEl = document.getElementById('fade');
    this.screenEls = [...document.querySelectorAll('.screen')];
    this._announceTimer = 0;
    this._subTimer = 0;
    this._hintTimer = 0;
    this._toastTimer = 0;
    this._lastHud = {};

    this._wire();
    this._paintIcons();
  }

  _paintIcons() {
    document.querySelectorAll('[data-icon]').forEach((el) => {
      el.innerHTML = ICON(el.dataset.icon);
    });
  }

  _wire() {
    document.querySelectorAll('[data-nav]').forEach((el) => {
      el.addEventListener('click', () => {
        this.game.audio.unlock();
        this.game.audio.ui();
        this.game.navigate(el.dataset.nav);
      });
    });
    document.getElementById('result-again')?.addEventListener('click', () => this.game.restartHunt());
    document.getElementById('result-hub')?.addEventListener('click', () => this.game.goHub());
    document.getElementById('resume-btn')?.addEventListener('click', () => this.game.setPaused(false));
    document.getElementById('abandon-btn')?.addEventListener('click', () => this.game.abandonHunt());
    document.getElementById('pause-btn')?.addEventListener('click', () => this.game.setPaused(true));
    document.getElementById('reset-save')?.addEventListener('click', () => this.game.resetProgress());
    document.getElementById('touch-lock')?.addEventListener('click', () => this.game.toggleLock());

    const questGrid = document.getElementById('quest-grid');
    questGrid?.addEventListener('click', (e) => {
      const card = e.target.closest('[data-quest]');
      if (!card) return;
      this.game.audio.unlock();
      this.game.audio.ui();
      this.game.startHunt(card.dataset.quest);
    });

    document.getElementById('hub-weapon-switch')?.addEventListener('click', (e) => {
      const b = e.target.closest('[data-weapon]');
      if (!b) return;
      this.game.setWeapon(b.dataset.weapon);
    });

    document.getElementById('smith-weapons')?.addEventListener('click', (e) => {
      const b = e.target.closest('[data-smith-weapon]');
      if (!b) return;
      this.smithWeapon = b.dataset.smithWeapon;
      this.game.audio.ui();
      this.refreshSmith();
    });
    document.getElementById('smith-detail')?.addEventListener('click', (e) => {
      const upgrade = e.target.closest('[data-upgrade]');
      if (upgrade) { this.game.upgradeWeapon(this.smithWeapon); return; }
      const skin = e.target.closest('[data-skin]');
      if (skin) {
        const idx = Number(skin.dataset.skin);
        if (skin.dataset.locked === '1') this.game.unlockSkin(this.smithWeapon, idx);
        else this.game.equipSkin(this.smithWeapon, idx);
      }
    });

    // settings
    const bindRange = (id, key, suffix, apply) => {
      const el = document.getElementById(id);
      if (!el) return;
      el.addEventListener('input', () => {
        const v = Number(el.value);
        this.game.save.settings[key] = v;
        document.getElementById(id + '-val').textContent = v + (suffix || '');
        this.game.applySettings();
        this.game.saveProgress();
      });
    };
    bindRange('set-master', 'master');
    bindRange('set-music', 'music');
    bindRange('set-sfx', 'sfx');
    bindRange('set-sens', 'sens');

    const toggle = (id, key, after) => {
      const el = document.getElementById(id);
      if (!el) return;
      el.addEventListener('change', () => {
        this.game.save.settings[key] = el.checked;
        this.game.saveProgress();
        after?.(el.checked);
      });
    };
    toggle('set-lefty', 'lefty', () => this.applySettings());
    toggle('set-touch', 'touch', () => this.applySettings());
    toggle('set-shake', 'shake');
  }

  // ---------------- screen management ----------------
  showScreen(name) {
    this.screen = name;
    this.screenEls.forEach((el) => el.classList.add('hidden'));
    if (!name) return;
    const el = document.getElementById('screen-' + name);
    if (el) el.classList.remove('hidden');
    if (name === 'hub') this.refreshHub();
    if (name === 'quests') this.refreshQuests();
    if (name === 'smith') this.refreshSmith();
    if (name === 'settings') this.refreshSettings();
  }

  hideAllScreens() {
    this.screenEls.forEach((el) => el.classList.add('hidden'));
    this.screen = null;
  }

  showHuntHud(show) {
    this.huntEls.root.classList.toggle('hidden', !show);
  }

  applySettings() {
    const s = this.game.save.settings;
    document.body.classList.toggle('lefty', !!s.lefty);
    this.applyTouchVisibility();
  }

  applyTouchVisibility(inHunt = this.game.state === 'hunt' || this.game.state === 'pause') {
    const s = this.game.save.settings;
    let touch = s.touch;
    if (touch === null || touch === undefined) {
      touch = window.matchMedia('(pointer: coarse)').matches || navigator.maxTouchPoints > 0;
    }
    this.huntEls.touch.classList.toggle('hidden', !(touch && inHunt));
    this.huntEls.cameraHint.classList.toggle('show', !touch && inHunt);
    this.huntEls.cameraHint.innerHTML = '<kbd>Click</kbd> to capture mouse · <kbd>F</kbd> lock on · drag to look';
    this.touchMode = touch;
  }

  // ---------------- hub ----------------
  refreshHub() {
    const s = this.game.save;
    const w = WEAPONS[s.weapon];
    const lvl = s.weaponLevels[s.weapon];
    document.getElementById('hub-weapon-icon').innerHTML = weaponArt(w.id);
    document.getElementById('hub-weapon-name').textContent = w.name;
    document.getElementById('hub-weapon-desc').textContent = w.desc;
    const skinName = w.skins[s.skins[w.id]]?.name || w.skins[0].name;
    document.getElementById('hub-weapon-stats').innerHTML = `
      <div class="mini-stat"><span>POWER</span><b>${'◆'.repeat(Math.round(w.power))}</b></div>
      <div class="mini-stat"><span>SPEED</span><b>${'◆'.repeat(Math.round(w.speed))}</b></div>
      <div class="mini-stat"><span>LEVEL</span><b>${lvl}</b></div>`;
    document.getElementById('hub-weapon-switch').innerHTML = WEAPON_ORDER.map((id) =>
      `<button class="wsw ${id === w.id ? 'on' : ''}" data-weapon="${id}">${WEAPONS[id].short}</button>`).join('');
    document.getElementById('hub-skin-line').innerHTML = `<span>SKIN · <b>${skinName}</b></span><span>ATK ×${(1 + 0.16 * (lvl - 1)).toFixed(2)}</span>`;

    const matCount = Object.values(s.materials).reduce((a, b) => a + b, 0);
    document.getElementById('hub-stats').innerHTML = `
      <div class="stat-chip">ZENNY <b>${s.zenny.toLocaleString()}</b></div>
      <div class="stat-chip">MATERIALS <b>${matCount}</b></div>
      <div class="stat-chip">HUNTS <b>${s.stats.wins}/${s.stats.hunts}</b></div>`;
    document.getElementById('hub-note').textContent = s.stats.wins > 0
      ? `A hunter's work is never done. ${s.stats.wins} hunt${s.stats.wins > 1 ? 's' : ''} cleared.`
      : 'Progress saves automatically. Your first hunt awaits.';
    this.applySettings();
  }

  // ---------------- quests ----------------
  refreshQuests() {
    const s = this.game.save;
    const grid = document.getElementById('quest-grid');
    grid.innerHTML = QUESTS.map((q) => {
      const [c1, c2] = q.palette;
      const rewards = Object.entries(q.rewards).map(([id, range]) => {
        const shown = Array.isArray(range) ? `${range[0]}–${range[1]}` : range;
        return `<span class="mat-chip"><i class="mat-dot" style="background:${matColor(id)}"></i>${MATERIALS[id].name} ×${shown}</span>`;
      }).join('');
      const cleared = s.cleared[q.id];
      return `<article class="quest-card ${cleared ? 'cleared' : ''}" data-quest="${q.id}">
        <div class="q-art" style="background:radial-gradient(ellipse at 50% 55%, ${c1}cc, ${c2}22 62%, transparent 82%), linear-gradient(160deg, ${c2}, #0a1a16)">${MONSTER_ART[q.monster](c1, c2)}</div>
        <span class="q-rank">${q.rank}</span>
        ${cleared ? '<span class="q-cleared">CLEARED</span>' : ''}
        <div class="q-body">
          <h3>${q.name}</h3>
          <div class="q-sub">${q.monsterName} · ${q.arena} arena</div>
          <div class="q-meta"><span>◷ 10:00</span><span>⚔ ${q.hint}</span></div>
          <p class="q-desc">${q.desc}</p>
          <div class="q-rewards">${rewards}</div>
          <div class="q-launch"><span>ACCEPT QUEST</span><div class="q-arrow">›</div></div>
        </div>
      </article>`;
    }).join('');
    const matCount = Object.values(s.materials).reduce((a, b) => a + b, 0);
    document.getElementById('quest-material-pill').textContent = `ZENNY ${s.zenny.toLocaleString()} · MAT ${matCount}`;
    const w = WEAPONS[s.weapon];
    document.getElementById('quest-loadout').innerHTML = `<span>LOADOUT</span><b style="color:var(--gold-hi)">${w.name} · Lv.${s.weaponLevels[w.id]}</b><span>·</span><span>${w.skins[s.skins[w.id]].name}</span>`;
  }

  // ---------------- blacksmith ----------------
  refreshSmith() {
    const s = this.game.save;
    const w = WEAPONS[this.smithWeapon];
    const lvl = s.weaponLevels[this.smithWeapon];
    const skinIdx = s.skins[this.smithWeapon];
    document.getElementById('smith-weapons').innerHTML = WEAPON_ORDER.map((id) => {
      const ww = WEAPONS[id];
      return `<button class="smith-w ${id === this.smithWeapon ? 'on' : ''}" data-smith-weapon="${id}">
        <span class="wicon">${weaponArt(id)}</span>
        <span>${ww.name}<small>LV. ${s.weaponLevels[id]} · ${ww.skins[s.skins[id]].name}</small></span>
      </button>`;
    }).join('');

    const cost = upgradeCost(this.smithWeapon, lvl + 1);
    const maxed = lvl >= 5;
    const affordable = cost && canAfford(cost, s.materials);
    const costHTML = maxed ? '<span class="cost-chip">MAXIMUM FORGE</span>' : Object.entries(cost).map(([id, qty]) => {
      const have = s.materials[id] || 0;
      return `<span class="cost-chip ${have < qty ? 'lacking' : ''}"><i class="mat-dot" style="background:${matColor(id)}"></i>${MATERIALS[id].name} ${have}/${qty}</span>`;
    }).join('');

    const skinsHTML = w.skins.map((sk, i) => {
      const unlocked = s.unlockedSkins[this.smithWeapon].includes(i);
      const equipped = i === skinIdx;
      const reqMet = lvl >= sk.reqLevel;
      const canUnlock = sk.cost && canAfford(sk.cost, s.materials) && reqMet;
      const label = unlocked ? (equipped ? 'EQUIPPED' : 'EQUIP') : (!reqMet ? `LV. ${sk.reqLevel}` : canUnlock ? 'UNLOCK' : 'MATERIALS');
      return `<button class="skin-card ${equipped ? 'on' : ''} ${unlocked ? '' : 'locked'}" data-skin="${i}" data-locked="${unlocked ? 0 : 1}">
        <span class="skin-swatch" style="background:linear-gradient(120deg,#${sk.blade.toString(16).padStart(6, '0')},#${(sk.accent || sk.shield || 0x888888).toString(16).padStart(6, '0')})"></span>
        ${sk.name}<small>${label}</small>
      </button>`;
    }).join('');

    document.getElementById('smith-detail').innerHTML = `
      <div class="sd-head">
        <div class="sd-art">${weaponArt(w.id)}</div>
        <div class="sd-title">
          <h3>${w.name}</h3>
          <p>${w.desc}</p>
        </div>
      </div>
      <div class="sd-stats">
        <div class="sd-stat"><span>RAW DAMAGE</span><b>${Math.round(w.combo[0].dmg * (1 + 0.16 * (lvl - 1)))} <em>Lv.${lvl}</em></b></div>
        <div class="sd-stat"><span>SPEED</span><b>${w.speed} / 5</b></div>
        <div class="sd-stat"><span>REACH</span><b>${w.range} / 5</b></div>
      </div>
      <div class="upgrade-row">
        <div style="flex:1;min-width:200px">
          <h4 class="upgrade-title">Forge Upgrade ${maxed ? '' : `→ Lv.${lvl + 1}`}</h4>
          <p class="upgrade-sub">+16% damage per level · unlocks new skins</p>
          <div>${costHTML}</div>
        </div>
        <button class="btn primary" data-upgrade="1" ${maxed || !affordable ? 'disabled' : ''}>${maxed ? 'FULLY FORGED' : 'UPGRADE'}</button>
      </div>
      <div class="skins">
        <h4>WEAPON SKINS</h4>
        <div class="skin-grid">${skinsHTML}</div>
      </div>`;

    const entries = Object.entries(s.materials).filter(([, v]) => v > 0);
    const matHTML = entries.length
      ? entries.map(([id, v]) => `<div class="inv-row"><i class="mat-dot" style="background:${matColor(id)}"></i><span>${MATERIALS[id].name}</span><b>${v}</b></div>`).join('')
      : '<div class="inv-empty">No materials yet.<br>Accept a quest and break some monster parts.</div>';
    document.getElementById('smith-inventory-list').innerHTML = matHTML + `<div class="inv-row" style="margin-top:10px;border-top:1px solid var(--line);padding-top:12px"><i class="mat-dot" style="background:var(--gold)"></i><span>Zenny</span><b>${s.zenny}</b></div>`;
    document.getElementById('smith-materials').textContent = `ZENNY ${s.zenny.toLocaleString()}`;
  }

  // ---------------- settings ----------------
  refreshSettings() {
    const s = this.game.save.settings;
    const setRange = (id, key) => {
      const el = document.getElementById(id);
      if (el) el.value = s[key];
      const val = document.getElementById(id + '-val');
      if (val) val.textContent = s[key];
    };
    setRange('set-master', 'master');
    setRange('set-music', 'music');
    setRange('set-sfx', 'sfx');
    setRange('set-sens', 'sens');
    document.getElementById('set-lefty').checked = !!s.lefty;
    document.getElementById('set-touch').checked = !!(s.touch ?? (window.matchMedia('(pointer: coarse)').matches || navigator.maxTouchPoints > 0));
    document.getElementById('set-shake').checked = s.shake !== false;
  }

  // ---------------- HUD ----------------
  setupHud(quest) {
    const h = this.huntEls;
    h.questName.textContent = quest.name.toUpperCase();
    h.monsterName.textContent = quest.monsterName;
    h.monsterPhase.textContent = 'CALM';
    h.monsterPhase.className = 'phase-tag';
    h.timerText.textContent = '10:00';
    h.timer.classList.remove('low');
    h.itemCount.textContent = HUNT_POTIONS;
    h.touchItemCount.textContent = HUNT_POTIONS;
    h.charge.classList.add('hidden');
    h.comboMeter.classList.remove('on');
    h.comboPips.forEach((p) => p.classList.remove('on'));
    h.monsterFill.style.transform = 'scaleX(1)';
    h.hpFill.style.transform = 'scaleX(1)';
    h.stamFill.style.transform = 'scaleX(1)';
    h.hpText.textContent = '100';
    h.stamText.textContent = '100';
    h.hp.classList.remove('low');
    h.root.classList.remove('hidden');
    this.showHuntHud(true);
    this.applyTouchVisibility(true);
  }

  setParts(parts) {
    this.huntEls.partChips.innerHTML = parts.map((p) =>
      `<span class="part-chip ${p.weak ? 'weak' : ''}" data-part="${p.id}">${p.label}</span>`).join('');
    this._parts = parts;
  }

  updateHud(state) {
    const h = this.huntEls;
    const hpPct = Math.max(0, state.hp / state.maxHp);
    const stPct = Math.max(0, state.stamina / state.maxStamina);
    const mPct = Math.max(0, state.monsterHp / state.monsterMaxHp);
    if (this._lastHud.hp !== hpPct) {
      h.hpFill.style.transform = `scaleX(${hpPct})`;
      h.hpText.textContent = Math.ceil(state.hp);
      h.hp.classList.toggle('low', hpPct < 0.3);
      this._lastHud.hp = hpPct;
    }
    if (this._lastHud.st !== stPct) {
      h.stamFill.style.transform = `scaleX(${stPct})`;
      h.stamText.textContent = Math.round(state.stamina);
      this._lastHud.st = stPct;
    }
    if (this._lastHud.mhp !== mPct) {
      h.monsterFill.style.transform = `scaleX(${mPct})`;
      this._lastHud.mhp = mPct;
    }
    if (this._lastHud.phase !== state.phase) {
      const phase = state.phase;
      h.monsterPhase.textContent = phase === 'enraged' ? 'ENRAGED' : phase === 'tired' ? 'TIRED' : 'CALM';
      h.monsterPhase.className = 'phase-tag ' + (phase === 'normal' ? '' : phase);
      this._lastHud.phase = phase;
    }
    if (this._lastHud.time !== state.time) {
      const t = Math.max(0, state.time);
      const mm = Math.floor(t / 60).toString().padStart(2, '0');
      const ss = Math.floor(t % 60).toString().padStart(2, '0');
      h.timerText.textContent = `${mm}:${ss}`;
      h.timer.classList.toggle('low', t <= 60);
      this._lastHud.time = state.time;
    }
    if (this._lastHud.items !== state.potions) {
      h.itemCount.textContent = state.potions;
      h.touchItemCount.textContent = state.potions;
      this._lastHud.items = state.potions;
    }
    if (this._lastHud.combo !== state.combo) {
      h.comboMeter.classList.toggle('on', state.combo > 0);
      h.comboPips.forEach((p, i) => p.classList.toggle('on', i < state.combo));
      this._lastHud.combo = state.combo;
    }
    if (this._lastHud.charge !== state.charge) {
      if (state.charge > 0) {
        h.charge.classList.remove('hidden');
        h.chargePips.forEach((p, i) => p.classList.toggle('on', i < state.charge));
        h.charge.querySelector('b').textContent = ['CHARGE', 'CHARGE I', 'CHARGE II', 'CHARGE III'][Math.min(3, state.charge)];
      } else {
        h.charge.classList.add('hidden');
      }
      this._lastHud.charge = state.charge;
    }
    if (this._lastHud.lock !== state.locked) {
      h.lock.classList.toggle('hidden', !state.locked);
      h.touchLock.classList.toggle('active', !!state.locked);
      this._lastHud.lock = state.locked;
    }
    if (this._parts && this._lastHud.parts !== state.partsVersion) {
      const map = new Map((state.brokenParts || []).map((p) => [p.id, p]));
      for (const p of this._parts) {
        const chip = h.partChips.querySelector(`[data-part="${p.id}"]`);
        if (!chip) continue;
        chip.classList.toggle('broken', map.has(p.id));
      }
      this._lastHud.parts = state.partsVersion;
    }
  }

  announce(text, cls = '', dur = 2.2) {
    const el = this.huntEls.announce;
    el.textContent = text;
    el.className = 'announce show ' + cls;
    clearTimeout(this._announceTimer);
    this._announceTimer = setTimeout(() => el.classList.remove('show'), dur * 1000);
  }

  subtitle(text, dur = 2.2) {
    const el = this.huntEls.subtitle;
    el.textContent = text;
    el.classList.add('show');
    clearTimeout(this._subTimer);
    this._subTimer = setTimeout(() => el.classList.remove('show'), dur * 1000);
  }

  hint(text, dur = 2.4) {
    const el = this.huntEls.hint;
    el.textContent = text;
    el.classList.add('show');
    clearTimeout(this._hintTimer);
    this._hintTimer = setTimeout(() => el.classList.remove('show'), dur * 1000);
  }

  damage(screenPos, text, cls = '', label = '') {
    if (!screenPos || !screenPos.visible) return;
    const el = document.createElement('div');
    el.className = 'dmg ' + cls;
    el.textContent = text;
    const jitter = (Math.random() - 0.5) * 26;
    el.style.left = `${screenPos.x + jitter}px`;
    el.style.top = `${screenPos.y}px`;
    this.damageLayer.appendChild(el);
    if (label) {
      const lb = document.createElement('div');
      lb.className = 'dmg-label';
      lb.textContent = label;
      lb.style.left = `${screenPos.x + jitter}px`;
      lb.style.top = `${screenPos.y - 22}px`;
      this.damageLayer.appendChild(lb);
      setTimeout(() => lb.remove(), 850);
    }
    setTimeout(() => el.remove(), 950);
  }

  flash(kind = 'hurt') {
    const el = this.flashEl;
    el.className = 'flash ' + kind;
    requestAnimationFrame(() => requestAnimationFrame(() => el.classList.remove(kind)));
  }

  toast(text, dur = 2.6) {
    const el = this.toastEl;
    el.textContent = text;
    el.classList.add('show');
    clearTimeout(this._toastTimer);
    this._toastTimer = setTimeout(() => el.classList.remove('show'), dur * 1000);
  }

  setFade(on) {
    this.fadeEl.classList.toggle('on', on);
  }

  showPause(show) {
    document.getElementById('screen-pause').classList.toggle('hidden', !show);
  }

  // ---------------- result ----------------
  showResult(data) {
    const { won, quest, rewards, zenny, stats, reason } = data;
    document.getElementById('result-eyebrow').textContent = won ? 'QUEST COMPLETE' : 'QUEST FAILED';
    document.getElementById('result-title').textContent = won ? 'Victory' : reason === 'timeout' ? 'Time Expired' : 'Fallen Hunter';
    document.getElementById('result-sub').textContent = won
      ? `${quest.monsterName} has fallen. The guild will remember this hunt.`
      : reason === 'timeout'
        ? 'The monster slipped away as the last light faded. Bring a sharper blade next time.'
        : 'The wilds are unforgiving. Rest, reforge, and return.';
    const crest = document.getElementById('result-crest');
    crest.className = 'result-crest' + (won ? '' : ' defeat');
    crest.innerHTML = `<svg viewBox="0 0 64 64"><path d="M32 3 40 21 60 23 45 37 50 60 32 48 14 60 19 37 4 23 24 21Z"/></svg>`;

    const statsHTML = [
      ['TIME', stats.time],
      ['PARTS BROKEN', stats.breaks],
      ['DAMAGE DEALT', Math.round(stats.damage)],
      ['POTIONS LEFT', stats.potions],
    ].map(([k, v]) => `<div class="rs"><span>${k}</span><b>${v}</b></div>`).join('');
    document.getElementById('result-stats').innerHTML = statsHTML;

    const rows = Object.entries(rewards).filter(([, v]) => v > 0).map(([id, v]) =>
      `<div class="reward-row"><i class="mat-dot" style="background:${matColor(id)}"></i>${MATERIALS[id].name}<b>+${v}</b></div>`).join('');
    document.getElementById('reward-list').innerHTML = rows || '<div class="reward-row" style="opacity:.6">No materials recovered.</div>';
    document.getElementById('reward-zenny').textContent = won ? `+${zenny} ZENNY` : 'NO REWARD';
    document.getElementById('part-note').textContent = won
      ? `${stats.breaks} part${stats.breaks === 1 ? '' : 's'} broken · bonus materials awarded for each break.`
      : 'Complete the hunt to keep your spoils.';
    this.hideAllScreens();
    this.screenEls.forEach((el) => el.classList.add('hidden'));
    document.getElementById('screen-result').classList.remove('hidden');
    this.screen = 'result';
    this.showHuntHud(false);
  }

  hideResult() {
    document.getElementById('screen-result').classList.add('hidden');
  }
}

// ============================================================
// IRONFANG — low-poly weapon models
// ============================================================
import * as THREE from 'three';

const metal = (color, opts = {}) => new THREE.MeshStandardMaterial({
  color, metalness: 0.55, roughness: 0.38, flatShading: true, ...opts,
});
const dark = (color) => new THREE.MeshStandardMaterial({ color, metalness: 0.1, roughness: 0.85, flatShading: true });
const accent = (color, glow = 0) => new THREE.MeshStandardMaterial({
  color, metalness: 0.7, roughness: 0.3, flatShading: true,
  emissive: glow, emissiveIntensity: glow ? 1.6 : 0,
});

function bladeGeometry(width, length, thickness, taper = 0.55, curve = 0) {
  const s = new THREE.Shape();
  const w = width / 2;
  s.moveTo(-w, 0);
  s.lineTo(w, 0);
  if (curve) {
    s.quadraticCurveTo(w * (1 - curve), length * 0.55, w * 0.25 + curve * w, length * 0.92);
    s.lineTo(curve * w, length);
    s.quadraticCurveTo(-w * 0.7, length * 0.6, -w, 0);
  } else {
    s.lineTo(w * (1 - taper * 0.2), length * 0.72);
    s.lineTo(0, length);
    s.lineTo(-w * (1 - taper * 0.2), length * 0.72);
    s.closePath();
  }
  const g = new THREE.ExtrudeGeometry(s, { depth: thickness, bevelEnabled: false, curveSegments: 3 });
  g.translate(0, 0, -thickness / 2);
  g.computeVertexNormals();
  return g;
}

function addTip(group, x, y, z, name) {
  const o = new THREE.Object3D();
  o.position.set(x, y, z);
  o.name = name;
  group.add(o);
  return o;
}

function buildGreatsword(skin) {
  const g = new THREE.Group();
  const blade = new THREE.Mesh(bladeGeometry(0.66, 2.5, 0.13, 0.5), metal(skin.blade));
  blade.position.y = 0.38;
  blade.castShadow = true;
  g.add(blade);

  // central fuller / accent
  const ridge = new THREE.Mesh(new THREE.BoxGeometry(0.075, 1.75, 0.05), accent(skin.accent, skin.glow || 0));
  ridge.position.set(0, 1.45, 0.075);
  g.add(ridge);
  const ridge2 = ridge.clone(); ridge2.position.z = -0.075; g.add(ridge2);

  // edge highlights
  const edgeMat = accent(skin.accent, skin.glow || 0);
  for (const sx of [-1, 1]) {
    const e = new THREE.Mesh(new THREE.BoxGeometry(0.035, 1.95, 0.14), edgeMat);
    e.position.set(sx * 0.3, 1.4, 0);
    e.rotation.z = -sx * 0.018;
    g.add(e);
  }

  const guard = new THREE.Mesh(new THREE.BoxGeometry(1.0, 0.14, 0.3), accent(skin.accent, skin.glow || 0));
  guard.position.y = 0.32;
  guard.castShadow = true;
  g.add(guard);

  for (const sx of [-1, 1]) {
    const spike = new THREE.Mesh(new THREE.ConeGeometry(0.1, 0.34, 4), metal(skin.blade));
    spike.position.set(sx * 0.55, 0.38, 0);
    spike.rotation.z = sx * Math.PI * 0.62;
    g.add(spike);
  }

  const grip = new THREE.Mesh(new THREE.CylinderGeometry(0.075, 0.085, 0.62, 6), dark(skin.grip));
  grip.position.y = -0.02;
  g.add(grip);
  for (let i = 0; i < 4; i++) {
    const wrap = new THREE.Mesh(new THREE.TorusGeometry(0.088, 0.022, 3, 6), dark(0x1a1410));
    wrap.rotation.x = Math.PI / 2;
    wrap.position.y = -0.2 + i * 0.14;
    g.add(wrap);
  }
  const pommel = new THREE.Mesh(new THREE.IcosahedronGeometry(0.11, 0), accent(skin.accent, skin.glow || 0));
  pommel.position.y = -0.38;
  g.add(pommel);

  addTip(g, 0, 2.9, 0, 'tip');
  addTip(g, 0, 0.5, 0, 'base');
  g.userData.length = 2.9;
  return g;
}

function buildDagger(skin, left) {
  const g = new THREE.Group();
  const blade = new THREE.Mesh(bladeGeometry(0.2, 1.05, 0.055, 0.15, left ? -0.32 : 0.32), metal(skin.blade));
  blade.position.y = 0.2;
  blade.castShadow = true;
  g.add(blade);

  const glow = new THREE.Mesh(new THREE.BoxGeometry(0.03, 0.75, 0.02), accent(skin.accent, skin.glow || 0));
  glow.position.set(0, 0.65, 0.04);
  g.add(glow);

  const guard = new THREE.Mesh(new THREE.BoxGeometry(0.34, 0.06, 0.12), accent(skin.accent, skin.glow || 0));
  guard.position.y = 0.2;
  g.add(guard);

  const grip = new THREE.Mesh(new THREE.CylinderGeometry(0.045, 0.052, 0.3, 6), dark(skin.grip));
  grip.position.y = 0.02;
  g.add(grip);

  const pom = new THREE.Mesh(new THREE.IcosahedronGeometry(0.065, 0), accent(skin.accent, skin.glow || 0));
  pom.position.y = -0.15;
  g.add(pom);

  addTip(g, 0, 1.3, 0, 'tip');
  addTip(g, 0, 0.2, 0, 'base');
  g.userData.length = 1.3;
  return g;
}

function buildShield(skin) {
  const g = new THREE.Group();
  const shape = new THREE.Shape();
  const r = 0.52;
  for (let i = 0; i < 6; i++) {
    const a = (Math.PI / 3) * i + Math.PI / 6;
    const x = Math.cos(a) * r, y = Math.sin(a) * r;
    if (i === 0) shape.moveTo(x, y); else shape.lineTo(x, y);
  }
  shape.closePath();
  const geo = new THREE.ExtrudeGeometry(shape, { depth: 0.1, bevelEnabled: true, bevelSize: 0.03, bevelThickness: 0.03, bevelSegments: 1 });
  geo.translate(0, 0, -0.05);
  const face = new THREE.Mesh(geo, metal(skin.shield, { metalness: 0.35, roughness: 0.55 }));
  face.castShadow = true;
  g.add(face);

  const rim = new THREE.Mesh(new THREE.TorusGeometry(0.46, 0.035, 4, 12), accent(skin.accent, skin.glow || 0));
  rim.position.z = 0.065;
  g.add(rim);

  const boss = new THREE.Mesh(new THREE.IcosahedronGeometry(0.15, 0), accent(skin.accent, skin.glow || 0));
  boss.position.z = 0.1;
  g.add(boss);

  for (let i = 0; i < 6; i++) {
    const a = (Math.PI / 3) * i + Math.PI / 6;
    const stud = new THREE.Mesh(new THREE.ConeGeometry(0.045, 0.12, 4), metal(skin.blade));
    stud.position.set(Math.cos(a) * 0.39, Math.sin(a) * 0.39, 0.07);
    stud.rotation.x = Math.PI / 2;
    g.add(stud);
  }
  return g;
}

function buildSnS(skin) {
  const g = new THREE.Group();
  const blade = new THREE.Mesh(bladeGeometry(0.22, 1.4, 0.07, 0.6), metal(skin.blade));
  blade.position.y = 0.22;
  blade.castShadow = true;
  g.add(blade);

  const fuller = new THREE.Mesh(new THREE.BoxGeometry(0.035, 0.9, 0.02), accent(skin.accent, skin.glow || 0));
  fuller.position.set(0, 0.8, 0.045);
  g.add(fuller);

  const guard = new THREE.Mesh(new THREE.BoxGeometry(0.44, 0.07, 0.16), accent(skin.accent, skin.glow || 0));
  guard.position.y = 0.22;
  g.add(guard);
  const grip = new THREE.Mesh(new THREE.CylinderGeometry(0.045, 0.055, 0.3, 6), dark(skin.grip));
  grip.position.y = 0.02;
  g.add(grip);
  const pom = new THREE.Mesh(new THREE.IcosahedronGeometry(0.06, 0), accent(skin.accent, skin.glow || 0));
  pom.position.y = -0.16;
  g.add(pom);

  addTip(g, 0, 1.68, 0, 'tip');
  addTip(g, 0, 0.35, 0, 'base');
  g.userData.length = 1.68;
  return g;
}

export function createWeaponModel(id, skin, level = 1) {
  const boost = level >= 4 ? 0.5 : 0;
  const s = { ...skin };
  if (boost && skin.glow) s.glow = skin.glow + 0x111111 * 0;
  let right = null, left = null;
  if (id === 'greatsword') right = buildGreatsword(s);
  else if (id === 'dualblades') { right = buildDagger(s, false); left = buildDagger(s, true); }
  else { right = buildSnS(s); left = buildShield(s); }

  if (level >= 5) {
    for (const grp of [right, left]) {
      if (!grp) continue;
      grp.traverse((o) => {
        if (o.isMesh && o.material && o.material.emissive) {
          const m = o.material.clone();
          m.emissive = new THREE.Color(skin.accent || 0xe8b45a);
          m.emissiveIntensity = 0.22;
          o.material = m;
        }
      });
    }
  }
  return { right, left };
}

export function weaponRigHandFor(id) {
  return id === 'swordshield' ? 'left' : 'right';
}

// ============================================================
// IRONFANG — particles, slash trails, ground telegraphs
// ============================================================
import * as THREE from 'three';

const MAX_PARTICLES = 700;

export class FX {
  constructor(scene) {
    this.scene = scene;
    this.effects = [];
    this.trails = [];
    this.time = 0;
    this._initParticles();
  }

  _initParticles() {
    const geo = new THREE.BufferGeometry();
    this.pPos = new Float32Array(MAX_PARTICLES * 3);
    this.pCol = new Float32Array(MAX_PARTICLES * 3);
    for (let i = 0; i < MAX_PARTICLES; i++) {
      this.pPos[i * 3 + 1] = -999;
    }
    geo.setAttribute('position', new THREE.BufferAttribute(this.pPos, 3));
    geo.setAttribute('color', new THREE.BufferAttribute(this.pCol, 3));
    const mat = new THREE.PointsMaterial({
      size: 0.2, vertexColors: true, transparent: true, opacity: 1,
      blending: THREE.AdditiveBlending, depthWrite: false, sizeAttenuation: true,
    });
    this.particles = new THREE.Points(geo, mat);
    this.particles.frustumCulled = false;
    this.scene.add(this.particles);
    this.parts = Array.from({ length: MAX_PARTICLES }, () => ({
      active: false, x: 0, y: 0, z: 0, vx: 0, vy: 0, vz: 0, life: 0, max: 1,
      r: 1, g: 1, b: 1, grav: 9,
    }));
    this.pIndex = 0;
  }

  burst(pos, color, count = 12, speed = 4, size = 1, opts = {}) {
    const c = new THREE.Color(color);
    const { gravity = 11, spread = 1, up = 0.6, life = 0.55 } = opts;
    for (let i = 0; i < count; i++) {
      const p = this.parts[this.pIndex];
      const idx = this.pIndex;
      this.pIndex = (this.pIndex + 1) % MAX_PARTICLES;
      p.active = true;
      p.x = pos.x + (Math.random() - 0.5) * spread;
      p.y = pos.y + (Math.random() - 0.5) * spread;
      p.z = pos.z + (Math.random() - 0.5) * spread;
      const theta = Math.random() * Math.PI * 2;
      const sp = speed * (0.35 + Math.random() * 0.9);
      p.vx = Math.cos(theta) * sp;
      p.vz = Math.sin(theta) * sp;
      p.vy = (Math.random() * 0.9 + up) * speed * 0.7;
      p.grav = gravity;
      p.life = p.max = life * (0.6 + Math.random() * 0.8);
      p.r = c.r; p.g = c.g; p.b = c.b;
      this.pPos[idx * 3] = p.x;
      this.pPos[idx * 3 + 1] = p.y;
      this.pPos[idx * 3 + 2] = p.z;
    }
    this.particles.geometry.attributes.position.needsUpdate = true;
    this.particles.geometry.attributes.color.needsUpdate = true;
  }

  dust(pos, count = 6, color = 0x9b8a6a) {
    this.burst(pos, color, count, 2.4, 1, { gravity: 2.5, up: 0.15, life: 0.75, spread: 1.4 });
  }

  spark(pos, color, strong = false) {
    this.burst(pos, color, strong ? 22 : 10, strong ? 6 : 4, 1, { gravity: 13, up: 0.5, life: strong ? 0.6 : 0.4 });
  }

  slashFlash(pos, yaw, color, scale = 1, tilt = 0) {
    const geo = new THREE.RingGeometry(0.55 * scale, 1.0 * scale, 20, 1, -0.7, 1.4);
    const mat = new THREE.MeshBasicMaterial({
      color, transparent: true, opacity: 0.9, side: THREE.DoubleSide,
      blending: THREE.AdditiveBlending, depthWrite: false,
    });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.position.copy(pos);
    mesh.rotation.set(-Math.PI / 2 + tilt, yaw, 0);
    this.scene.add(mesh);
    this.effects.push({ mesh, life: 0.26, max: 0.26, kind: 'flash', scaleFrom: 0.7, scaleTo: 1.8 });
  }

  telegraphCircle(pos, radius, duration, color = 0xff3322) {
    const group = new THREE.Group();
    group.position.set(pos.x, 0.045, pos.z);
    const ring = new THREE.Mesh(
      new THREE.RingGeometry(radius * 0.88, radius, 44),
      new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.75, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false })
    );
    ring.rotation.x = -Math.PI / 2;
    const fill = new THREE.Mesh(
      new THREE.CircleGeometry(radius, 40),
      new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.12, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false })
    );
    fill.rotation.x = -Math.PI / 2;
    fill.position.y = -0.01;
    group.add(ring, fill);
    this.scene.add(group);
    const e = { mesh: group, ring, fill, radius, life: duration, max: duration, kind: 'telegraph' };
    this.effects.push(e);
    return e;
  }

  telegraphCone(pos, yaw, radius, angle, duration, color = 0xff3b22) {
    const half = angle / 2;
    const seg = 24;
    const verts = [];
    for (let i = 0; i < seg; i++) {
      const a0 = -half + (angle * i) / seg;
      const a1 = -half + (angle * (i + 1)) / seg;
      verts.push(0, 0, 0, Math.sin(a0) * radius, 0, Math.cos(a0) * radius, Math.sin(a1) * radius, 0, Math.cos(a1) * radius);
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.Float32BufferAttribute(verts, 3));
    geo.computeVertexNormals();
    const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.22, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.position.set(pos.x, 0.05, pos.z);
    mesh.rotation.y = yaw;
    this.scene.add(mesh);
    const edgeGeo = new THREE.BufferGeometry().setFromPoints([
      new THREE.Vector3(0, 0.01, 0),
      new THREE.Vector3(Math.sin(-half) * radius, 0.01, Math.cos(-half) * radius),
      new THREE.Vector3(Math.sin(half) * radius, 0.01, Math.cos(half) * radius),
      new THREE.Vector3(0, 0.01, 0),
    ]);
    const edge = new THREE.Line(edgeGeo, new THREE.LineBasicMaterial({ color, transparent: true, opacity: 0.9, blending: THREE.AdditiveBlending }));
    mesh.add(edge);
    const e = { mesh, life: duration, max: duration, kind: 'telegraph', fill: mat, baseOpacity: 0.22 };
    this.effects.push(e);
    return e;
  }

  telegraphLine(start, yaw, length, width, duration, color = 0xff3b22) {
    const group = new THREE.Group();
    group.position.set(start.x, 0.05, start.z);
    group.rotation.y = yaw;
    const plane = new THREE.Mesh(
      new THREE.PlaneGeometry(width, length, 1, 1),
      new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.2, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false })
    );
    plane.rotation.x = -Math.PI / 2;
    plane.position.z = length / 2;
    group.add(plane);
    // borders
    const edgeMat = new THREE.LineBasicMaterial({ color, transparent: true, opacity: 0.9, blending: THREE.AdditiveBlending });
    for (const sx of [-1, 1]) {
      const geo = new THREE.BufferGeometry().setFromPoints([
        new THREE.Vector3((sx * width) / 2, 0.01, 0),
        new THREE.Vector3((sx * width) / 2, 0.01, length),
      ]);
      group.add(new THREE.Line(geo, edgeMat));
    }
    this.scene.add(group);
    const e = { mesh: group, life: duration, max: duration, kind: 'telegraph', fill: plane.material, baseOpacity: 0.2 };
    this.effects.push(e);
    return e;
  }

  shockwave(pos, radius = 3, color = 0xffd08a, duration = 0.5) {
    const geo = new THREE.RingGeometry(0.6, 1, 40);
    const mesh = new THREE.Mesh(geo, new THREE.MeshBasicMaterial({
      color, transparent: true, opacity: 0.9, side: THREE.DoubleSide,
      blending: THREE.AdditiveBlending, depthWrite: false,
    }));
    mesh.rotation.x = -Math.PI / 2;
    mesh.position.set(pos.x, 0.08, pos.z);
    mesh.scale.setScalar(radius / 2);
    this.scene.add(mesh);
    this.effects.push({ mesh, life: duration, max: duration, kind: 'wave', scaleFrom: radius / 3, scaleTo: radius * 1.2 });
  }

  createTrail(color, width = 0.55) {
    const maxPts = 22;
    const geo = new THREE.BufferGeometry();
    const pos = new Float32Array(maxPts * 2 * 3);
    const col = new Float32Array(maxPts * 2 * 3);
    geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    geo.setAttribute('color', new THREE.BufferAttribute(col, 3));
    const idx = [];
    for (let i = 0; i < maxPts - 1; i++) {
      const a = i * 2, b = i * 2 + 1, c = i * 2 + 2, d = i * 2 + 3;
      idx.push(a, b, c, b, d, c);
    }
    geo.setIndex(idx);
    geo.setDrawRange(0, 0);
    const mat = new THREE.MeshBasicMaterial({
      vertexColors: true, transparent: true, opacity: 1,
      side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false,
    });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.frustumCulled = false;
    this.scene.add(mesh);
    const c = new THREE.Color(color);
    const trail = {
      mesh, geo, points: [], color: c, width,
      add(base, tip, life = 0.22) {
        this.points.push({ base: base.clone(), tip: tip.clone(), life, age: 0 });
        if (this.points.length > maxPts) this.points.shift();
      },
      update(dt) {
        for (const p of this.points) p.age += dt;
        this.points = this.points.filter((p) => p.age < p.life);
        const n = this.points.length;
        if (n < 2) { geo.setDrawRange(0, 0); return; }
        for (let i = 0; i < n; i++) {
          const p = this.points[i];
          const f = Math.max(0, 1 - p.age / p.life);
          const w = 0.12 + 0.5 * f;
          const dx = p.tip.x - p.base.x, dy = p.tip.y - p.base.y, dz = p.tip.z - p.base.z;
          const len = Math.hypot(dx, dz) || 1;
          const nx = (-dz / len) * w, nz = (dx / len) * w;
          const k = i * 6;
          pos[k] = p.base.x; pos[k + 1] = p.base.y; pos[k + 2] = p.base.z;
          pos[k + 3] = p.base.x + nx; pos[k + 4] = p.base.y + dy * 0.4; pos[k + 5] = p.base.z + nz;
          const gl = f * f;
          for (let j = 0; j < 2; j++) {
            col[k + j * 3] = this.color.r * gl;
            col[k + j * 3 + 1] = this.color.g * gl;
            col[k + j * 3 + 2] = this.color.b * gl;
          }
        }
        geo.attributes.position.needsUpdate = true;
        geo.attributes.color.needsUpdate = true;
        geo.setDrawRange(0, (n - 1) * 6);
      },
      dispose() {
        this.scene.remove(mesh);
        geo.dispose(); mat.dispose();
      },
    };
    this.trails.push(trail);
    return trail;
  }

  update(dt) {
    this.time += dt;
    // particles
    let any = false;
    for (let i = 0; i < MAX_PARTICLES; i++) {
      const p = this.parts[i];
      if (!p.active) continue;
      any = true;
      p.life -= dt;
      if (p.life <= 0) {
        p.active = false;
        this.pPos[i * 3 + 1] = -999;
        this.pCol[i * 3] = this.pCol[i * 3 + 1] = this.pCol[i * 3 + 2] = 0;
        continue;
      }
      p.vy -= p.grav * dt;
      p.x += p.vx * dt; p.y += p.vy * dt; p.z += p.vz * dt;
      p.vx *= 0.985; p.vz *= 0.985;
      if (p.y < 0.05) { p.y = 0.05; p.vy *= -0.28; p.vx *= 0.7; p.vz *= 0.7; }
      const f = p.life / p.max;
      this.pPos[i * 3] = p.x; this.pPos[i * 3 + 1] = p.y; this.pPos[i * 3 + 2] = p.z;
      this.pCol[i * 3] = p.r * f; this.pCol[i * 3 + 1] = p.g * f; this.pCol[i * 3 + 2] = p.b * f;
    }
    if (any) {
      this.particles.geometry.attributes.position.needsUpdate = true;
      this.particles.geometry.attributes.color.needsUpdate = true;
    }
    for (const t of this.trails) t.update(dt);

    // telegraphs / flashes / waves
    for (let i = this.effects.length - 1; i >= 0; i--) {
      const e = this.effects[i];
      e.life -= dt;
      const f = Math.max(0, e.life / e.max);
      if (e.kind === 'telegraph') {
        const pulse = 0.7 + Math.sin(this.time * 16) * 0.22;
        if (e.fill) e.fill.opacity = (e.baseOpacity || 0.2) * pulse * (0.55 + 0.45 * (1 - f));
        if (e.ring) e.ring.material.opacity = 0.6 * pulse * f;
        e.mesh.scale.setScalar(1 + (1 - f) * 0.02);
      } else if (e.kind === 'wave') {
        const p = 1 - f;
        e.mesh.scale.setScalar(e.scaleFrom + (e.scaleTo - e.scaleFrom) * p);
        e.mesh.material.opacity = f * 0.85;
      } else if (e.kind === 'flash') {
        const p = 1 - f;
        e.mesh.scale.setScalar(e.scaleFrom + (e.scaleTo - e.scaleFrom) * p);
        e.mesh.material.opacity = f;
      }
      if (e.life <= 0) {
        this.scene.remove(e.mesh);
        e.mesh.traverse?.((o) => {
          if (o.geometry) o.geometry.dispose();
          if (o.material) o.material.dispose?.();
        });
        if (e.mesh.geometry) e.mesh.geometry.dispose();
        if (e.mesh.material) e.mesh.material.dispose();
        this.effects.splice(i, 1);
      }
    }
  }

  clear() {
    for (const t of this.trails) t.dispose();
    this.trails = [];
    for (const e of this.effects) {
      this.scene.remove(e.mesh);
      e.mesh.traverse?.((o) => {
        if (o.geometry) o.geometry.dispose();
        if (o.material) o.material.dispose?.();
      });
    }
    this.effects = [];
    for (const p of this.parts) p.active = false;
    for (let i = 0; i < MAX_PARTICLES; i++) { this.pPos[i * 3 + 1] = -999; this.pCol[i * 3] = 0; }
    this.particles.geometry.attributes.position.needsUpdate = true;
    this.particles.geometry.attributes.color.needsUpdate = true;
  }

  dispose() {
    this.clear();
    this.scene.remove(this.particles);
    this.particles.geometry.dispose();
    this.particles.material.dispose();
  }
}

// ============================================================
// IRONFANG — arenas: forest, volcano, frozen cave, hub camp
// ============================================================
import * as THREE from 'three';

const rand = (a, b) => a + Math.random() * (b - a);

function standard(color, opts = {}) {
  return new THREE.MeshStandardMaterial({ color, roughness: 0.92, metalness: 0.02, flatShading: true, ...opts });
}

const ARENAS = {
  forest: {
    name: 'Verdant Hollow', ground: 0x466d3c, ground2: 0x527a44, skyTop: 0x3e718c, skyHorizon: 0xf6bd7d, skyBottom: 0x2c3a27,
    fog: 0x9cb18a, fogDensity: 0.012, hemiSky: 0xb8d8d0, hemiGround: 0x3d4a2a, hemiIntensity: 0.85,
    sun: 0xffd4a0, sunIntensity: 1.55, sunPos: [-18, 26, 10],
    ambient: 0.2, weather: 'leaves', grassCount: 300, flowers: true,
  },
  volcano: {
    name: 'Cinder Caldera', ground: 0x3a2925, ground2: 0x48322b, skyTop: 0x1a0a0d, skyHorizon: 0xbe4a22, skyBottom: 0x140807,
    fog: 0x5f2418, fogDensity: 0.017, hemiSky: 0x8a3a28, hemiGround: 0x1c0d0b, hemiIntensity: 0.75,
    sun: 0xff9050, sunIntensity: 1.15, sunPos: [14, 20, -12],
    ambient: 0.16, weather: 'ash', grassCount: 0, lava: true,
  },
  ice: {
    name: 'Frostmaw Cavern', ground: 0xc8dce6, ground2: 0xb3cddc, skyTop: 0x0d1c36, skyHorizon: 0x6d9dc0, skyBottom: 0x0a1524,
    fog: 0x9fc0d4, fogDensity: 0.014, hemiSky: 0x9cc8ea, hemiGround: 0x3a4a58, hemiIntensity: 0.95,
    sun: 0xbfe2ff, sunIntensity: 1.2, sunPos: [-12, 24, -16],
    ambient: 0.3, weather: 'snow', grassCount: 0, ice: true,
  },
  hub: {
    name: "Hunter's Rest", ground: 0x4a6b3e, ground2: 0x567847, skyTop: 0x2c4964, skyHorizon: 0xe6a06b, skyBottom: 0x27341f,
    fog: 0x8a9a7a, fogDensity: 0.014, hemiSky: 0xb9c9d8, hemiGround: 0x3a4326, hemiIntensity: 0.7,
    sun: 0xffb075, sunIntensity: 1.2, sunPos: [-14, 18, 12],
    ambient: 0.24, weather: 'fireflies', grassCount: 220, hub: true,
  },
};

function skyDome(top, horizon, bottom) {
  const geo = new THREE.SphereGeometry(170, 24, 14);
  const mat = new THREE.ShaderMaterial({
    side: THREE.BackSide, depthWrite: false, fog: false,
    uniforms: {
      topColor: { value: new THREE.Color(top) },
      horizonColor: { value: new THREE.Color(horizon) },
      bottomColor: { value: new THREE.Color(bottom) },
    },
    vertexShader: `varying vec3 vPos; void main(){ vPos = position; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }`,
    fragmentShader: `uniform vec3 topColor; uniform vec3 horizonColor; uniform vec3 bottomColor; varying vec3 vPos;
      void main(){
        float h = normalize(vPos).y;
        vec3 c = mix(horizonColor, topColor, smoothstep(0.0, 0.65, h));
        c = mix(bottomColor, c, smoothstep(-0.25, 0.04, h));
        gl_FragColor = vec4(c, 1.0);
      }`,
  });
  return new THREE.Mesh(geo, mat);
}

function makeGround(cfg, radius = 38) {
  const geo = new THREE.PlaneGeometry(radius * 2.4, radius * 2.4, 26, 26);
  geo.rotateX(-Math.PI / 2);
  const colors = [];
  const c1 = new THREE.Color(cfg.ground), c2 = new THREE.Color(cfg.ground2);
  const pos = geo.attributes.position;
  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i), z = pos.getZ(i);
    const d = Math.hypot(x, z);
    const n = Math.sin(x * 0.35) * Math.cos(z * 0.28) * 0.5 + 0.5;
    const c = c1.clone().lerp(c2, n * 0.7 + Math.random() * 0.25);
    c.multiplyScalar(0.9 + Math.random() * 0.16);
    colors.push(c.r, c.g, c.b);
    // very subtle undulation away from the fighting center, flat in the middle
    const ramp = THREE.MathUtils.smoothstep(d, 12, 34);
    pos.setY(i, (Math.sin(x * 0.5) * Math.cos(z * 0.4) * 0.28) * ramp);
  }
  geo.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
  geo.computeVertexNormals();
  const mat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.97, metalness: 0, flatShading: true });
  const mesh = new THREE.Mesh(geo, mat);
  mesh.receiveShadow = true;
  return mesh;
}

function makeRock(size, color, mossColor) {
  const g = new THREE.Group();
  const geo = new THREE.IcosahedronGeometry(size, 0);
  const pos = geo.attributes.position;
  for (let i = 0; i < pos.count; i++) {
    pos.setXYZ(i, pos.getX(i) * rand(0.8, 1.2), pos.getY(i) * rand(0.65, 1.15), pos.getZ(i) * rand(0.8, 1.2));
  }
  geo.computeVertexNormals();
  const rock = new THREE.Mesh(geo, standard(color));
  rock.position.y = size * 0.55;
  rock.castShadow = true; rock.receiveShadow = true;
  g.add(rock);
  if (mossColor) {
    const moss = new THREE.Mesh(new THREE.IcosahedronGeometry(size * 0.72, 0), standard(mossColor));
    moss.scale.set(1, 0.35, 1);
    moss.position.y = size * 1.03;
    g.add(moss);
  }
  return g;
}

function makeTree(scale = 1) {
  const g = new THREE.Group();
  const trunk = new THREE.Mesh(new THREE.CylinderGeometry(0.18, 0.3, 2.2, 5), standard(0x4a3526));
  trunk.position.y = 1.1;
  trunk.castShadow = true;
  g.add(trunk);
  const layers = 3;
  for (let i = 0; i < layers; i++) {
    const r = 1.55 - i * 0.33;
    const h = 1.9 - i * 0.25;
    const cone = new THREE.Mesh(new THREE.ConeGeometry(r, h, 7), standard(i % 2 ? 0x3d6a3a : 0x467b40));
    cone.position.y = 2.2 + i * 1.05;
    cone.rotation.y = i * 0.6;
    cone.castShadow = true;
    g.add(cone);
  }
  // side branch
  const branch = new THREE.Mesh(new THREE.CylinderGeometry(0.07, 0.11, 1.1, 4), standard(0x4a3526));
  branch.position.set(0.5, 1.3, 0.1);
  branch.rotation.z = -0.9;
  g.add(branch);
  g.scale.setScalar(scale);
  return g;
}

function makeIceSpire(size = 1) {
  const g = new THREE.Group();
  const geo = new THREE.ConeGeometry(0.5 * size, 3.2 * size, 5);
  const mat = new THREE.MeshStandardMaterial({ color: 0x9fd6ec, roughness: 0.25, metalness: 0.15, flatShading: true, transparent: true, opacity: 0.92 });
  const m = new THREE.Mesh(geo, mat);
  m.position.y = 1.6 * size;
  m.rotation.z = rand(-0.12, 0.12);
  m.castShadow = true;
  g.add(m);
  const m2 = new THREE.Mesh(new THREE.ConeGeometry(0.22 * size, 1.6 * size, 4), mat.clone());
  m2.position.set(0.44 * size, 0.8 * size, 0.1);
  m2.rotation.z = 0.35;
  g.add(m2);
  return g;
}

function makeLavaPool(size) {
  const g = new THREE.Group();
  const geo = new THREE.CircleGeometry(size, 9);
  const mat = new THREE.MeshStandardMaterial({ color: 0xff5a14, emissive: 0xff3b00, emissiveIntensity: 2.1, roughness: 0.5 });
  const pool = new THREE.Mesh(geo, mat);
  pool.rotation.x = -Math.PI / 2;
  pool.position.y = 0.04;
  g.add(pool);
  const rim = new THREE.Mesh(new THREE.RingGeometry(size * 0.95, size * 1.22, 10), standard(0x2a1c18));
  rim.rotation.x = -Math.PI / 2;
  rim.position.y = 0.05;
  g.add(rim);
  const glow = new THREE.PointLight(0xff6a20, 6, size * 7, 2);
  glow.position.y = 1.2;
  g.add(glow);
  g.userData.pulse = mat;
  return g;
}

function makeCampfire() {
  const g = new THREE.Group();
  for (let i = 0; i < 5; i++) {
    const log = new THREE.Mesh(new THREE.CylinderGeometry(0.09, 0.09, 0.9, 5), standard(0x3d2a1d));
    log.rotation.z = Math.PI / 2;
    log.rotation.y = (i / 5) * Math.PI;
    log.position.y = 0.1;
    g.add(log);
  }
  const stone = new THREE.Mesh(new THREE.TorusGeometry(0.55, 0.11, 4, 9), standard(0x5a5a52));
  stone.rotation.x = Math.PI / 2;
  stone.position.y = 0.07;
  g.add(stone);
  const flameMat = new THREE.MeshBasicMaterial({ color: 0xff9a3c, transparent: true, opacity: 0.9, blending: THREE.AdditiveBlending, depthWrite: false });
  const flames = [];
  for (let i = 0; i < 3; i++) {
    const f = new THREE.Mesh(new THREE.ConeGeometry(0.22 - i * 0.05, 0.7, 5), flameMat.clone());
    f.position.set(rand(-0.08, 0.08), 0.42 + i * 0.08, rand(-0.08, 0.08));
    g.add(f); flames.push(f);
  }
  const light = new THREE.PointLight(0xff9a4a, 12, 16, 2);
  light.position.y = 1;
  g.add(light);
  g.userData.flames = flames;
  g.userData.light = light;
  return g;
}

export function createArena(id, scene, renderer) {
  const isHub = id === 'hub';
  const cfg = ARENAS[id] || ARENAS.forest;
  const group = new THREE.Group();
  scene.add(group);

  scene.fog = new THREE.FogExp2(cfg.fog, cfg.fogDensity);
  const sky = skyDome(cfg.skyTop, cfg.skyHorizon, cfg.skyBottom);
  group.add(sky);

  // sun / moon disc
  const sunGeo = new THREE.CircleGeometry(7, 20);
  const sunMat = new THREE.MeshBasicMaterial({ color: id === 'ice' ? 0xd7efff : 0xffd9a0, transparent: true, opacity: 0.85, fog: false, depthWrite: false });
  const sun = new THREE.Mesh(sunGeo, sunMat);
  sun.position.set(cfg.sunPos[0] * 5, cfg.sunPos[1] * 4.2, cfg.sunPos[2] * 5);
  sun.lookAt(0, 0, 0);
  group.add(sun);

  // lights
  const hemi = new THREE.HemisphereLight(cfg.hemiSky, cfg.hemiGround, cfg.hemiIntensity);
  group.add(hemi);
  const amb = new THREE.AmbientLight(0xffffff, cfg.ambient);
  group.add(amb);
  const sunLight = new THREE.DirectionalLight(cfg.sun, cfg.sunIntensity);
  sunLight.position.set(...cfg.sunPos);
  sunLight.castShadow = true;
  sunLight.shadow.mapSize.set(1024, 1024);
  sunLight.shadow.camera.left = -22;
  sunLight.shadow.camera.right = 22;
  sunLight.shadow.camera.top = 22;
  sunLight.shadow.camera.bottom = -22;
  sunLight.shadow.camera.near = 1;
  sunLight.shadow.camera.far = 70;
  sunLight.shadow.bias = -0.0018;
  group.add(sunLight);
  group.add(sunLight.target);

  const ground = makeGround(cfg);
  group.add(ground);

  // arena ring marking
  const ringGeo = new THREE.RingGeometry(13.2, 13.7, 64);
  const ringMat = new THREE.MeshBasicMaterial({ color: id === 'volcano' ? 0xff8a4a : id === 'ice' ? 0x8fd6f2 : 0xd9c89a, transparent: true, opacity: 0.12, side: THREE.DoubleSide, depthWrite: false });
  const ring = new THREE.Mesh(ringGeo, ringMat);
  ring.rotation.x = -Math.PI / 2;
  ring.position.y = 0.06;
  group.add(ring);

  const obstacles = [];
  const scenery = [];
  const dummy = new THREE.Object3D();
  const rng = (a, b) => a + Math.random() * (b - a);

  // helper to place props without blocking the start lanes
  const clearOfStarts = (x, z, r) => {
    const starts = [[0, 12], [0, -8], [0, 2]];
    return starts.every(([sx, sz]) => Math.hypot(x - sx, z - sz) > r + 4.2);
  };

  // ---------- perimeter cliffs ----------
  const cliffColor = id === 'forest' ? 0x3d4a34 : id === 'volcano' ? 0x201514 : id === 'ice' ? 0x7f9aad : 0x3a4934;
  for (let i = 0; i < 26; i++) {
    const a = (i / 26) * Math.PI * 2 + rng(-0.05, 0.05);
    const dist = rng(34, 41);
    const size = rng(3.2, 6.5);
    const rock = makeRock(size, cliffColor, null);
    rock.position.set(Math.cos(a) * dist, -size * 0.25, Math.sin(a) * dist);
    rock.rotation.y = rng(0, 6);
    scenery.push(rock);
    group.add(rock);
  }

  // ---------- arena props ----------
  if (id === 'forest' || isHub) {
    const treeCount = isHub ? 10 : 17;
    for (let i = 0; i < treeCount; i++) {
      const a = rng(0, Math.PI * 2);
      const dist = rng(15, 29);
      const x = Math.cos(a) * dist, z = Math.sin(a) * dist;
      if (!clearOfStarts(x, z, 2.2)) { i--; continue; }
      const tree = makeTree(rng(0.85, 1.35));
      tree.position.set(x, 0, z);
      tree.rotation.y = rng(0, 6);
      group.add(tree);
      obstacles.push({ x, z, r: 0.7, h: 4 });
    }
    for (let i = 0; i < 9; i++) {
      const a = rng(0, Math.PI * 2);
      const dist = rng(12, 28);
      const x = Math.cos(a) * dist, z = Math.sin(a) * dist;
      if (!clearOfStarts(x, z, 1.5)) { i--; continue; }
      const size = rng(0.7, 1.8);
      const rock = makeRock(size, 0x6b7268, 0x567a45);
      rock.position.set(x, 0, z);
      rock.rotation.y = rng(0, 6);
      group.add(rock);
      obstacles.push({ x, z, r: size * 0.92, h: size });
    }
    // mushrooms / flowers dots
    const dotGeo = new THREE.SphereGeometry(0.07, 4, 3);
    const dotMat = new THREE.MeshBasicMaterial({ color: 0xffd27a });
    for (let i = 0; i < 26; i++) {
      const a = rng(0, Math.PI * 2), dist = rng(5, 26);
      const d = new THREE.Mesh(dotGeo, Math.random() > 0.5 ? dotMat : new THREE.MeshBasicMaterial({ color: 0xb28bff }));
      d.position.set(Math.cos(a) * dist, 0.06, Math.sin(a) * dist);
      group.add(d);
    }
  } else if (id === 'volcano') {
    for (let i = 0; i < 14; i++) {
      const a = rng(0, Math.PI * 2);
      const dist = rng(14, 30);
      const x = Math.cos(a) * dist, z = Math.sin(a) * dist;
      if (!clearOfStarts(x, z, 2)) { i--; continue; }
      const size = rng(0.9, 2.6);
      const rock = makeRock(size, 0x2b1d1a, null);
      rock.position.set(x, 0, z);
      rock.rotation.y = rng(0, 6);
      group.add(rock);
      obstacles.push({ x, z, r: size * 0.9, h: size });
    }
    for (let i = 0; i < 5; i++) {
      const a = rng(0, Math.PI * 2);
      const dist = rng(16, 27);
      const x = Math.cos(a) * dist, z = Math.sin(a) * dist;
      const pool = makeLavaPool(rng(1.2, 2.6));
      pool.position.set(x, 0, z);
      group.add(pool);
      scenery.push(pool);
    }
    // jagged spires
    for (let i = 0; i < 8; i++) {
      const a = rng(0, Math.PI * 2), dist = rng(26, 33);
      const spike = new THREE.Mesh(new THREE.ConeGeometry(rng(0.6, 1.4), rng(4, 8), 5), standard(0x241615));
      spike.position.set(Math.cos(a) * dist, 2, Math.sin(a) * dist);
      spike.rotation.z = rng(-0.15, 0.15);
      spike.castShadow = true;
      group.add(spike);
    }
  } else if (id === 'ice') {
    for (let i = 0; i < 16; i++) {
      const a = rng(0, Math.PI * 2);
      const dist = rng(14, 30);
      const x = Math.cos(a) * dist, z = Math.sin(a) * dist;
      if (!clearOfStarts(x, z, 2)) { i--; continue; }
      const spire = makeIceSpire(rng(0.7, 2.0));
      spire.position.set(x, 0, z);
      spire.rotation.y = rng(0, 6);
      group.add(spire);
      obstacles.push({ x, z, r: 0.7, h: 3 });
    }
    for (let i = 0; i < 8; i++) {
      const a = rng(0, Math.PI * 2);
      const dist = rng(13, 28);
      const x = Math.cos(a) * dist, z = Math.sin(a) * dist;
      if (!clearOfStarts(x, z, 1.6)) { i--; continue; }
      const size = rng(0.9, 2.2);
      const rock = makeRock(size, 0x86a4b6, 0xcfeaf5);
      rock.position.set(x, 0, z);
      rock.rotation.y = rng(0, 6);
      group.add(rock);
      obstacles.push({ x, z, r: size * 0.9, h: size });
    }
    // frozen arch
    const archMat = new THREE.MeshStandardMaterial({ color: 0xa6d8ea, roughness: 0.2, metalness: 0.1, flatShading: true, transparent: true, opacity: 0.9 });
    for (let side = -1; side <= 1; side += 2) {
      const pillar = new THREE.Mesh(new THREE.ConeGeometry(1.1, 9, 5), archMat);
      pillar.position.set(side * 8, 4.4, -24);
      pillar.rotation.z = side * 0.14;
      group.add(pillar);
    }
  }

  // campfire for hub
  let campfire = null;
  if (isHub) {
    campfire = makeCampfire();
    campfire.position.set(3.2, 0, 9);
    group.add(campfire);
    // tent
    const tent = new THREE.Group();
    const tentMat = new THREE.MeshStandardMaterial({ color: 0x8a5a3a, roughness: 0.9, flatShading: true });
    const body = new THREE.Mesh(new THREE.ConeGeometry(2.2, 2.6, 4), tentMat);
    body.position.y = 1.3;
    body.rotation.y = Math.PI / 4;
    body.castShadow = true;
    tent.add(body);
    const opening = new THREE.Mesh(new THREE.ConeGeometry(0.8, 1.6, 3), new THREE.MeshBasicMaterial({ color: 0x1a0f08 }));
    opening.position.set(0, 0.8, 1.55);
    opening.rotation.x = 0.2;
    tent.add(opening);
    tent.position.set(-4, 0, 10);
    tent.rotation.y = 0.4;
    group.add(tent);
    // crates
    for (let i = 0; i < 3; i++) {
      const crate = new THREE.Mesh(new THREE.BoxGeometry(0.7, 0.7, 0.7), standard(0x6a4a2e));
      crate.position.set(-2.4 + i * 0.8, 0.35, 7.5 + (i % 2) * 0.7);
      crate.rotation.y = rng(0, 1);
      crate.castShadow = true;
      group.add(crate);
    }
  }

  // ---------- grass ----------
  let grass = null;
  let grassData = [];
  const grassCount = cfg.grassCount || 0;
  if (grassCount > 0) {
    const bladeGeo = new THREE.PlaneGeometry(0.13, 0.75, 1, 2);
    bladeGeo.translate(0, 0.375, 0);
    const bladeMat = new THREE.MeshLambertMaterial({ color: 0x6b9a4e, side: THREE.DoubleSide });
    grass = new THREE.InstancedMesh(bladeGeo, bladeMat, grassCount);
    grass.castShadow = false;
    grass.frustumCulled = false;
    group.add(grass);
    for (let i = 0; i < grassCount; i++) {
      const a = rng(0, Math.PI * 2), dist = rng(4.5, 31);
      const x = Math.cos(a) * dist, z = Math.sin(a) * dist;
      grassData.push({ x, z, phase: rng(0, 6.5), scale: rng(0.7, 1.9), rot: rng(0, 3.1) });
      dummy.position.set(x, 0, z);
      dummy.rotation.set(0, grassData[i].rot, 0);
      dummy.scale.setScalar(grassData[i].scale);
      dummy.updateMatrix();
      grass.setMatrixAt(i, dummy.matrix);
    }
    grass.instanceMatrix.needsUpdate = true;
    const snowGrass = id === 'ice';
    if (snowGrass) bladeMat.color.set(0x9fc0b8);
  }

  // ---------- weather / ambience ----------
  const weather = { points: null, data: [], kind: cfg.weather };
  if (cfg.weather === 'ash' || cfg.weather === 'snow' || cfg.weather === 'leaves') {
    const count = id === 'volcano' ? 520 : 460;
    const geo = new THREE.BufferGeometry();
    const arr = new Float32Array(count * 3);
    const col = new Float32Array(count * 3);
    const base = cfg.weather === 'snow' ? new THREE.Color(0xffffff) : cfg.weather === 'ash' ? new THREE.Color(0x8e8078) : new THREE.Color(0xd8b06a);
    for (let i = 0; i < count; i++) {
      const x = rng(-38, 38), y = rng(0, 26), z = rng(-38, 38);
      arr[i * 3] = x; arr[i * 3 + 1] = y; arr[i * 3 + 2] = z;
      weather.data.push({ vy: cfg.weather === 'snow' ? rng(0.7, 1.7) : cfg.weather === 'ash' ? rng(0.35, 0.9) : rng(0.4, 1.1), drift: rng(0.2, 0.9), phase: rng(0, 6.5), size: rng(0.5, 1.2) });
      const c = base.clone().offsetHSL(0, 0, rng(-0.12, 0.12));
      col[i * 3] = c.r; col[i * 3 + 1] = c.g; col[i * 3 + 2] = c.b;
    }
    geo.setAttribute('position', new THREE.BufferAttribute(arr, 3));
    geo.setAttribute('color', new THREE.BufferAttribute(col, 3));
    const mat = new THREE.PointsMaterial({
      size: cfg.weather === 'snow' ? 0.16 : cfg.weather === 'ash' ? 0.12 : 0.14,
      vertexColors: true, transparent: true, opacity: cfg.weather === 'snow' ? 0.85 : 0.7,
      depthWrite: false, blending: cfg.weather === 'ash' ? THREE.NormalBlending : THREE.AdditiveBlending,
      sizeAttenuation: true,
    });
    const pts = new THREE.Points(geo, mat);
    pts.frustumCulled = false;
    group.add(pts);
    weather.points = pts;
    weather.arr = arr;
  }

  // fireflies
  let fireflies = null, fireflyBase = null;
  if (cfg.weather === 'fireflies' || id === 'forest') {
    const count = isHub ? 42 : 26;
    const geo = new THREE.BufferGeometry();
    const arr = new Float32Array(count * 3);
    fireflyBase = [];
    for (let i = 0; i < count; i++) {
      const a = rng(0, Math.PI * 2), d = rng(6, 26);
      const x = Math.cos(a) * d, z = Math.sin(a) * d, y = rng(0.7, 3.4);
      arr[i * 3] = x; arr[i * 3 + 1] = y; arr[i * 3 + 2] = z;
      fireflyBase.push({ x, y, z, phase: rng(0, 6.5), amp: rng(0.4, 1.4) });
    }
    geo.setAttribute('position', new THREE.BufferAttribute(arr, 3));
    const mat = new THREE.PointsMaterial({ color: 0xd8ff9a, size: 0.14, transparent: true, opacity: 0.9, blending: THREE.AdditiveBlending, depthWrite: false });
    fireflies = new THREE.Points(geo, mat);
    fireflies.frustumCulled = false;
    group.add(fireflies);
  }

  // embers for volcano
  let embers = null;
  let emberData = [];
  if (id === 'volcano') {
    const count = 130;
    const geo = new THREE.BufferGeometry();
    const arr = new Float32Array(count * 3);
    for (let i = 0; i < count; i++) {
      const a = rng(0, Math.PI * 2), d = rng(4, 30);
      arr[i * 3] = Math.cos(a) * d; arr[i * 3 + 1] = rng(0, 6); arr[i * 3 + 2] = Math.sin(a) * d;
      emberData.push({ vy: rng(0.6, 1.8), phase: rng(0, 6.5), drift: rng(-0.4, 0.4) });
    }
    geo.setAttribute('position', new THREE.BufferAttribute(arr, 3));
    const mat = new THREE.PointsMaterial({ color: 0xff7a2a, size: 0.12, transparent: true, opacity: 0.85, blending: THREE.AdditiveBlending, depthWrite: false });
    embers = new THREE.Points(geo, mat);
    embers.frustumCulled = false;
    group.add(embers);
    emberData = { list: emberData, arr };
  }

  const grassDummy = new THREE.Object3D();
  let t = 0;

  const api = {
    id, cfg, group, obstacles, bounds: 31,
    playerStart: new THREE.Vector3(0, 0, 12),
    monsterStart: new THREE.Vector3(0, 0, -8),
    hubPlayer: new THREE.Vector3(0, 0, 2),
    name: cfg.name,
    update(dt, elapsed, camPos) {
      t = elapsed;
      if (grass) {
        for (let i = 0; i < grassData.length; i++) {
          const d = grassData[i];
          const sway = Math.sin(t * 1.7 + d.phase) * 0.16 + Math.sin(t * 0.7 + d.phase * 0.6) * 0.08;
          grassDummy.position.set(d.x, 0, d.z);
          grassDummy.rotation.set(sway * 0.6, d.rot, sway);
          grassDummy.scale.set(d.scale, d.scale, d.scale);
          grassDummy.updateMatrix();
          grass.setMatrixAt(i, grassDummy.matrix);
        }
        grass.instanceMatrix.needsUpdate = true;
      }
      if (weather.points) {
        const arr = weather.arr;
        const cx = camPos ? camPos.x : 0, cz = camPos ? camPos.z : 0;
        for (let i = 0; i < weather.data.length; i++) {
          const d = weather.data[i];
          let y = arr[i * 3 + 1] - d.vy * dt;
          let x = arr[i * 3] + Math.sin(t * 0.8 + d.phase) * d.drift * dt;
          let z = arr[i * 3 + 2] + Math.cos(t * 0.6 + d.phase) * d.drift * dt * 0.5;
          if (y < 0.05) { y = 24; x = cx + rng(-34, 34); z = cz + rng(-34, 34); }
          if (Math.abs(x - cx) > 40) x = cx + Math.sign(cx - x) * 38;
          if (Math.abs(z - cz) > 40) z = cz + Math.sign(cz - z) * 38;
          arr[i * 3] = x; arr[i * 3 + 1] = y; arr[i * 3 + 2] = z;
        }
        weather.points.geometry.attributes.position.needsUpdate = true;
      }
      if (fireflies) {
        const arr = fireflies.geometry.attributes.position.array;
        for (let i = 0; i < fireflyBase.length; i++) {
          const b = fireflyBase[i];
          arr[i * 3] = b.x + Math.sin(t * 0.5 + b.phase) * b.amp;
          arr[i * 3 + 1] = b.y + Math.sin(t * 0.9 + b.phase * 1.7) * 0.35;
          arr[i * 3 + 2] = b.z + Math.cos(t * 0.6 + b.phase) * b.amp;
        }
        fireflies.geometry.attributes.position.needsUpdate = true;
        fireflies.material.opacity = 0.7 + Math.sin(t * 2.2) * 0.2;
      }
      if (embers) {
        const arr = emberData.arr;
        for (let i = 0; i < emberData.list.length; i++) {
          const d = emberData.list[i];
          let y = arr[i * 3 + 1] + d.vy * dt;
          arr[i * 3] += Math.sin(t * 1.2 + d.phase) * 0.22 * dt + d.drift * dt;
          arr[i * 3 + 2] += Math.cos(t + d.phase) * 0.18 * dt;
          if (y > 9) { y = 0.2; }
          arr[i * 3 + 1] = y;
        }
        embers.geometry.attributes.position.needsUpdate = true;
      }
      for (const s of scenery) {
        if (s.userData.pulse) {
          const p = 1.8 + Math.sin(t * 2.4 + s.position.x) * 0.55;
          s.userData.pulse.emissiveIntensity = p;
        }
      }
      if (campfire) {
        campfire.userData.flames.forEach((f, i) => {
          f.scale.setScalar(0.9 + Math.sin(t * 8 + i * 2) * 0.12);
          f.position.y = 0.4 + i * 0.08 + Math.sin(t * 6 + i) * 0.03;
        });
        if (campfire.userData.light) campfire.userData.light.intensity = 10 + Math.sin(t * 7.3) * 2.2;
      }
      // gentle light drift
      sunLight.position.x = cfg.sunPos[0] + Math.sin(t * 0.04) * 2;
    },
    dispose() {
      scene.remove(group);
      scene.fog = null;
      group.traverse((o) => {
        if (o.geometry) o.geometry.dispose();
        if (o.material) {
          if (Array.isArray(o.material)) o.material.forEach((m) => m.dispose());
          else o.material.dispose();
        }
      });
    },
  };
  return api;
}

// ============================================================
// IRONFANG — hunter: movement, combos, dodge, guard, potions
// ============================================================
import * as THREE from 'three';
import { WEAPONS, POTION_HEAL, HUNT_POTIONS } from './data.js';
import { createWeaponModel } from './weapons.js';

const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const lerp = (a, b, t) => a + (b - a) * t;
const damp = (a, b, lambda, dt) => lerp(a, b, 1 - Math.exp(-lambda * dt));
const angleDiff = (a, b) => {
  let d = a - b;
  while (d > Math.PI) d -= Math.PI * 2;
  while (d < -Math.PI) d += Math.PI * 2;
  return d;
};
const easeOut = (t) => 1 - Math.pow(1 - t, 2);
const easeInOut = (t) => (t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2);

function mat(color, opts = {}) {
  return new THREE.MeshStandardMaterial({ color, roughness: 0.72, metalness: 0.12, flatShading: true, ...opts });
}

export class Player {
  constructor(scene, game, weaponId, level, skinIndex) {
    this.scene = scene;
    this.game = game;
    this.weaponId = weaponId;
    this.weapon = WEAPONS[weaponId];
    this.level = level;
    this.skins = this.weapon.skins;
    this.skin = this.skins[skinIndex] || this.skins[0];
    this.dmgScale = 1 + 0.16 * (level - 1);

    this.hp = 100;
    this.maxHp = 100;
    this.stamina = 100;
    this.maxStamina = 100;
    this.potions = HUNT_POTIONS;
    this.state = 'idle';
    this.facing = Math.PI;
    this.pos = new THREE.Vector3(0, 0, 12);
    this.rollDir = new THREE.Vector2();
    this.time = 0;
    this.walkPhase = 0;
    this.speedSmooth = 0;
    this.staminaDelay = 0;
    this.comboIndex = 0;
    this.comboTimer = 0;
    this.queued = false;
    this.queuedFinisher = false;
    this.charging = false;
    this.chargeTime = 0;
    this.chargeLevel = 0;
    this.demonMode = false;
    this.demonDrainAcc = 0;
    this.invuln = 0;
    this.hurtTimer = 0;
    this.staggerTimer = 0;
    this.dodgeTimer = 0;
    this.potionTimer = 0;
    this.potionHealed = false;
    this.attack = null;
    this.specialHeld = false;
    this.specialTimer = 0;
    this.specialDone = false;
    this.blockFlash = 0;
    this.knock = new THREE.Vector3();
    this.damageDealt = 0;
    this.trailPoints = 0;
    this.attackHeldPrior = false;

    this._tmp = new THREE.Vector3();
    this._tmp2 = new THREE.Vector3();
    this._camDir = new THREE.Vector3();
    this._camRight = new THREE.Vector3();

    this._build();
    this.trail = this.game.fx.createTrail(this.weapon.colors.trail);
    this.setPosition(this.pos);
  }

  // ------------------------------------------------------------
  _build() {
    const root = new THREE.Group();
    this.root = root;
    const model = new THREE.Group();
    this.model = model;
    root.add(model);

    const armorMat = mat(0x50656b, { metalness: 0.35, roughness: 0.5 });
    const clothMat = mat(0x2e4a42);
    const leatherMat = mat(0x5c432e);
    const goldMat = mat(0xc9a04e, { metalness: 0.6, roughness: 0.32 });
    const darkMat = mat(0x222a29);

    // hips
    const hips = new THREE.Group();
    hips.position.y = 0.92;
    model.add(hips);
    this.hips = hips;

    const belt = new THREE.Mesh(new THREE.CylinderGeometry(0.34, 0.36, 0.18, 6), leatherMat);
    belt.position.y = 0.02;
    hips.add(belt);

    // torso
    const torso = new THREE.Group();
    hips.add(torso);
    this.torso = torso;
    const chest = new THREE.Mesh(new THREE.CylinderGeometry(0.33, 0.4, 0.72, 6), armorMat);
    chest.position.y = 0.38;
    chest.castShadow = true;
    torso.add(chest);
    const chestPlate = new THREE.Mesh(new THREE.CylinderGeometry(0.335, 0.41, 0.36, 6, 1, true), goldMat);
    chestPlate.position.y = 0.5;
    chestPlate.scale.set(1.02, 1, 1.02);
    torso.add(chestPlate);
    const skirt = new THREE.Mesh(new THREE.CylinderGeometry(0.4, 0.5, 0.42, 6, 1, true), clothMat);
    skirt.position.y = -0.02;
    torso.add(skirt);

    // head
    const head = new THREE.Group();
    head.position.y = 0.84;
    torso.add(head);
    this.head = head;
    const skull = new THREE.Mesh(new THREE.IcosahedronGeometry(0.24, 0), armorMat);
    skull.scale.set(1, 1.05, 0.95);
    skull.castShadow = true;
    head.add(skull);
    const helm = new THREE.Mesh(new THREE.ConeGeometry(0.28, 0.34, 5), goldMat);
    helm.position.y = 0.15;
    helm.rotation.y = Math.PI / 5;
    head.add(helm);
    const visor = new THREE.Mesh(new THREE.BoxGeometry(0.36, 0.075, 0.1), new THREE.MeshStandardMaterial({ color: 0x1c2624, emissive: 0x6fffdc, emissiveIntensity: 1.5, roughness: 0.4 }));
    visor.position.set(0, 0.015, 0.2);
    head.add(visor);
    for (const s of [-1, 1]) {
      const horn = new THREE.Mesh(new THREE.ConeGeometry(0.06, 0.3, 4), goldMat);
      horn.position.set(s * 0.22, 0.22, 0.02);
      horn.rotation.z = -s * 0.55;
      head.add(horn);
    }

    // arms
    const makeArm = (side) => {
      const pivot = new THREE.Group();
      pivot.position.set(side * 0.4, 0.62, 0);
      torso.add(pivot);
      const upper = new THREE.Mesh(new THREE.CylinderGeometry(0.11, 0.1, 0.42, 5), armorMat);
      upper.position.y = -0.2;
      upper.castShadow = true;
      pivot.add(upper);
      const fore = new THREE.Mesh(new THREE.CylinderGeometry(0.095, 0.085, 0.34, 5), clothMat);
      fore.position.y = -0.53;
      pivot.add(fore);
      const shoulder = new THREE.Mesh(new THREE.IcosahedronGeometry(0.19, 0), goldMat);
      shoulder.scale.set(1, 0.8, 1);
      pivot.add(shoulder);
      const hand = new THREE.Object3D();
      hand.position.y = -0.72;
      pivot.add(hand);
      const fist = new THREE.Mesh(new THREE.IcosahedronGeometry(0.09, 0), leatherMat);
      fist.position.y = -0.7;
      pivot.add(fist);
      return { pivot, hand };
    };
    const left = makeArm(-1);
    const right = makeArm(1);
    this.armL = left.pivot;
    this.armR = right.pivot;
    this.handL = left.hand;
    this.handR = right.hand;

    // legs
    const makeLeg = (side) => {
      const pivot = new THREE.Group();
      pivot.position.set(side * 0.17, 0, 0);
      hips.add(pivot);
      const thigh = new THREE.Mesh(new THREE.CylinderGeometry(0.14, 0.12, 0.46, 5), clothMat);
      thigh.position.y = -0.23;
      thigh.castShadow = true;
      pivot.add(thigh);
      const shin = new THREE.Mesh(new THREE.CylinderGeometry(0.115, 0.09, 0.42, 5), armorMat);
      shin.position.y = -0.65;
      pivot.add(shin);
      const boot = new THREE.Mesh(new THREE.BoxGeometry(0.2, 0.14, 0.34), leatherMat);
      boot.position.set(0, -0.87, 0.05);
      pivot.add(boot);
      return pivot;
    };
    this.legL = makeLeg(-1);
    this.legR = makeLeg(1);

    // cape
    const capeGeo = new THREE.PlaneGeometry(0.6, 0.85, 2, 3);
    const cape = new THREE.Mesh(capeGeo, new THREE.MeshStandardMaterial({ color: 0x29443b, side: THREE.DoubleSide, roughness: 0.95, flatShading: true }));
    cape.position.set(0, 0.32, -0.28);
    torso.add(cape);
    this.cape = cape;

    // hunter's mark / scarf
    const scarf = new THREE.Mesh(new THREE.TorusGeometry(0.28, 0.06, 4, 8), mat(0xb2543a));
    scarf.rotation.x = Math.PI / 2;
    scarf.position.y = 0.74;
    torso.add(scarf);

    // weapon models
    const models = createWeaponModel(this.weaponId, this.skin, this.level);
    if (models.right) {
      this.handR.add(models.right);
      this.weaponR = models.right;
    }
    if (models.left) {
      this.handL.add(models.left);
      this.weaponL = models.left;
    }
    this.applyWeaponRest();

    // charge aura
    this.aura = new THREE.Mesh(
      new THREE.IcosahedronGeometry(1.1, 1),
      new THREE.MeshBasicMaterial({ color: 0xffc46a, transparent: true, opacity: 0.0, blending: THREE.AdditiveBlending, depthWrite: false, wireframe: true })
    );
    this.aura.position.y = 1.1;
    this.aura.scale.setScalar(0.8);
    model.add(this.aura);
    this.aura.visible = false;

    // demon aura
    this.demonAura = new THREE.Mesh(
      new THREE.IcosahedronGeometry(1.0, 1),
      new THREE.MeshBasicMaterial({ color: 0xb28bff, transparent: true, opacity: 0.12, blending: THREE.AdditiveBlending, depthWrite: false })
    );
    this.demonAura.position.y = 1.05;
    this.demonAura.visible = false;
    model.add(this.demonAura);

    root.traverse((o) => { if (o.isMesh) { o.castShadow = true; } });
    this.scene.add(root);
  }

  applyWeaponRest() {
    const id = this.weaponId;
    if (this.weaponR) {
      if (id === 'greatsword') this.weaponR.rotation.set(0.42, 0, -0.12);
      else if (id === 'dualblades') this.weaponR.rotation.set(1.35, 0.1, 0.15);
      else this.weaponR.rotation.set(0.45, 0, -0.05);
    }
    if (this.weaponL) {
      if (id === 'dualblades') this.weaponL.rotation.set(1.35, -0.1, -0.15);
      else if (id === 'swordshield') this.weaponL.rotation.set(0.2, -1.15, 0.2);
    }
  }

  setPosition(p) {
    this.pos.copy(p);
    this.pos.y = 0;
    this.root.position.copy(this.pos);
  }

  get center() {
    return this._tmp2.set(this.pos.x, 1.1, this.pos.z);
  }

  reset(p) {
    this.hp = this.maxHp;
    this.stamina = this.maxStamina;
    this.potions = HUNT_POTIONS;
    this.state = 'idle';
    this.attack = null;
    this.dead = false;
    this.invuln = 0;
    this.demonMode = false;
    this.charging = false;
    this.chargeTime = 0;
    this.chargeLevel = 0;
    this.comboIndex = 0;
    this.comboTimer = 0;
    this.queued = false;
    this.staggerTimer = 0;
    this.potionTimer = 0;
    this.damageDealt = 0;
    this.facing = Math.PI;
    this.setPosition(p);
    this.root.rotation.set(0, this.facing, 0);
    this._poseReset();
  }

  // ------------------------------------------------------------
  update(dt, input, camera, monster) {
    this.time += dt;
    if (this.dead) { this._animate(dt, input, camera); return; }
    this.invuln = Math.max(0, this.invuln - dt);
    this.hurtTimer = Math.max(0, this.hurtTimer - dt);
    this.staggerTimer = Math.max(0, this.staggerTimer - dt);

    const pressedAttack = input.consume('attack');
    const pressedSpecial = input.consume('special');
    const pressedDodge = input.consume('dodge');
    const pressedItem = input.consume('item');
    const move = input.updateMove();

    // camera basis
    camera.getWorldDirection(this._camDir);
    this._camDir.y = 0;
    if (this._camDir.lengthSq() < 0.001) this._camDir.set(0, 0, -1);
    this._camDir.normalize();
    this._camRight.set(-this._camDir.z, 0, this._camDir.x);
    const moveVec = this._tmp.copy(this._camRight).multiplyScalar(move.x).addScaledVector(this._camDir, move.z);
    const moving = move.mag > 0.08;

    const canAct = this.state !== 'dead' && this.staggerTimer <= 0;

    // ----- dodge -----
    if (pressedDodge && canAct && this.state !== 'dodge') {
      if (this.stamina >= 12) {
        this._startDodge(moveVec, moving);
      } else {
        this.game.ui.hint('Not enough stamina', 1.2);
      }
    }

    // ----- potion -----
    if (pressedItem && canAct && this.state !== 'dodge' && this.state !== 'attack') {
      this.usePotion();
    }

    // ----- special handling -----
    if (this.weaponId === 'dualblades') {
      if (pressedSpecial && canAct && this.state !== 'dodge') this._dualSpecial();
    } else if (this.weapon.canGuard) {
      if (input.held.special && (this.state === 'idle' || this.state === 'guard' || this.state === 'charge')) {
        this.specialTimer += dt;
        if (this.specialTimer > 0.16 && !this.specialDone) {
          this.specialDone = true;
          this.state = 'guard';
          this.charging = false;
          this.attack = null;
        }
      } else if (!input.held.special) {
        if (this.specialTimer > 0 && this.specialTimer <= 0.16 && !this.specialDone && canAct && this.state !== 'guard') {
          this._startFinisher();
        }
        this.specialTimer = 0;
        this.specialDone = false;
        if (this.state === 'guard') this.state = 'idle';
      }
      if (pressedSpecial && (this.state === 'attack')) this.queuedFinisher = true;
    }

    // ----- attack input -----
    if (pressedAttack && canAct && this.state !== 'dodge') {
      if (this.state === 'attack') {
        if (this.attack.phase !== 'windup') this.queued = true;
      } else if (this.state === 'charge') {
        // releasing handled below; a fresh tap releases the charge
        this._releaseCharge();
      } else if (this.state === 'guard') {
        this.state = 'idle';
        this._beginCombo();
      } else if (this.state === 'drink') {
        // ignore
      } else {
        this._beginCombo();
      }
    }

    if ((this.state === 'idle' || this.state === 'guard') && this.weaponId === 'greatsword' && input.held.attack && this.attackHeldPrior) {
      this._beginCharge();
    }
    this.attackHeldPrior = input.held.attack;

    // ----- state machine -----
    if (this.state === 'attack') this._updateAttack(dt, monster);
    else if (this.state === 'charge') this._updateCharge(dt, input);
    else if (this.state === 'dodge') this._updateDodge(dt);
    else if (this.state === 'drink') this._updatePotion(dt);
    else if (this.state === 'guard') {
      if (!input.held.special) this.state = 'idle';
    }

    // ----- combo timeout -----
    if (this.state !== 'attack') {
      if (this.comboTimer > 0) {
        this.comboTimer -= dt;
        if (this.comboTimer <= 0) this.comboIndex = 0;
      }
    }

    // ----- movement -----
    let allowMove = true, speedMul = 1;
    if (this.state === 'attack') { allowMove = false; }
    else if (this.state === 'charge') { allowMove = true; speedMul = 0.32; }
    else if (this.state === 'guard') { allowMove = true; speedMul = 0.38; }
    else if (this.state === 'drink') { allowMove = this.weaponId === 'swordshield'; speedMul = 0.55; }
    else if (this.state === 'dodge') { allowMove = false; }
    else if (this.staggerTimer > 0) { allowMove = false; }

    if (allowMove) {
      let speed = this.weapon.moveSpeed * speedMul;
      let sprinting = false;
      if (this.demonMode && this.state === 'idle') speed *= 1.1;
      if (moving && input.isSprint() && this.stamina > 2 && this.state === 'idle') {
        speed = this.weapon.sprintSpeed;
        sprinting = true;
        this._drainStamina(9 * dt);
      }
      if (sprinting && Math.random() < dt * 18) {
        this.game.fx.dust(this._tmp2.set(this.pos.x, 0.1, this.pos.z), 1, 0x8d7f65);
      }
      if (moving) {
        this.speedSmooth = damp(this.speedSmooth, speed, 14, dt);
        const targetYaw = Math.atan2(moveVec.x, moveVec.z);
        if (this.state !== 'guard' || !this.game.lockOn) {
          this.facing += angleDiff(targetYaw, this.facing) * (1 - Math.exp(-dt * 13));
        }
        const vx = moveVec.x * this.speedSmooth * move.mag;
        const vz = moveVec.z * this.speedSmooth * move.mag;
        this._move(vx * dt, vz * dt);
      } else {
        this.speedSmooth = damp(this.speedSmooth, 0, 12, dt);
      }
    } else {
      this.speedSmooth = damp(this.speedSmooth, 0, 16, dt);
    }

    // guard / locked facing
    if (this.state === 'guard' || (this.game.lockOn && monster && (this.state === 'attack' || moving === false))) {
      if (monster && !monster.dead) {
        const target = Math.atan2(monster.pos.x - this.pos.x, monster.pos.z - this.pos.z);
        this.facing += angleDiff(target, this.facing) * (1 - Math.exp(-dt * (this.state === 'guard' ? 10 : 5)));
      }
    }

    // knockback
    if (this.knock.lengthSq() > 0.001) {
      this._move(this.knock.x * dt, this.knock.z * dt);
      this.knock.multiplyScalar(Math.exp(-dt * 8));
    }

    // stamina
    this.staminaDelay = Math.max(0, this.staminaDelay - dt);
    if (this.demonMode) {
      this._drainStamina(this.weapon.demon.drain * dt);
      this.demonDrainAcc += dt;
      if (this.stamina <= 0) {
        this.demonMode = false;
        this.game.ui.announce('DEMON MODE ENDS', 'tired', 1.4);
        this.game.audio.notify();
      }
      if (this.demonDrainAcc > 0.08) {
        this.demonDrainAcc = 0;
        this.game.fx.burst(this._tmp2.set(this.pos.x, 1.0, this.pos.z), 0xb28bff, 2, 1.2, 1, { life: 0.5, gravity: -1.5 });
      }
    } else if (this.staminaDelay <= 0 && this.state !== 'dodge' && this.state !== 'guard') {
      this.stamina = Math.min(this.maxStamina, this.stamina + 27 * dt);
    }

    // charge aura visuals
    if (this.charging) {
      this.chargeTime += dt;
      const lvl = this._chargeLevelFromTime();
      if (lvl !== this.chargeLevel) {
        this.chargeLevel = lvl;
        if (lvl > 0) this.game.audio.charge(lvl);
      }
      this.aura.visible = true;
      this.aura.material.opacity = 0.1 + lvl * 0.08;
      this.aura.rotation.y += dt * 2;
      this.aura.scale.setScalar(0.8 + lvl * 0.18 + Math.sin(this.time * 8) * 0.04);
      if (Math.random() < dt * (8 + lvl * 8)) {
        this.game.fx.burst(this._tmp2.set(this.pos.x, 1.15, this.pos.z), this.weapon.colors.trail, 1, 0.7, 1, { life: 0.5, gravity: -2.5 });
      }
    } else {
      this.aura.visible = false;
    }
    if (this.demonMode) {
      this.demonAura.visible = true;
      this.demonAura.material.opacity = 0.09 + Math.sin(this.time * 6) * 0.03;
      this.demonAura.rotation.y -= dt * 1.2;
    } else {
      this.demonAura.visible = false;
    }

    // trail during active attack
    if (this.state === 'attack' && this.attack && this.attack.phase === 'active') {
      this._emitTrail();
    }

    this._animate(dt, input, camera, monster);
  }

  // ------------------------------------------------------------
  _move(dx, dz) {
    this.pos.x += dx;
    this.pos.z += dz;
    const arena = this.game.arena;
    const bounds = arena ? arena.bounds - 1.2 : 29;
    const d = Math.hypot(this.pos.x, this.pos.z);
    if (d > bounds) {
      this.pos.x = (this.pos.x / d) * bounds;
      this.pos.z = (this.pos.z / d) * bounds;
    }
    if (arena) {
      for (const o of arena.obstacles) {
        const dx2 = this.pos.x - o.x, dz2 = this.pos.z - o.z;
        const dist = Math.hypot(dx2, dz2);
        const min = o.r + 0.45;
        if (dist < min && dist > 0.0001) {
          this.pos.x = o.x + (dx2 / dist) * min;
          this.pos.z = o.z + (dz2 / dist) * min;
        }
      }
    }
    this.root.position.set(this.pos.x, 0, this.pos.z);
  }

  _drainStamina(n) {
    this.stamina = Math.max(0, this.stamina - n);
    this.staminaDelay = 0.6;
  }

  _beginCombo() {
    let idx = 0;
    if (this.comboTimer > 0) idx = Math.min(2, this.comboIndex + 1);
    this._startAttack(this.weapon.combo[idx], idx, false);
    this.game.audio.swing(this.weaponId, idx > 0);
  }

  _startFinisher() {
    this._startAttack(this.weapon.finisher, 2, true);
    this.game.audio.swing(this.weaponId, true);
    this.game.ui.announce(this.weapon.finisher.name.toUpperCase(), '', 1.1);
  }

  _startAttack(def, index, finisher = false) {
    this._autoAim();
    this.state = 'attack';
    this.attack = {
      def, index, finisher,
      phase: 'windup', timer: 0,
      hitsDone: 0, tickTimer: 0,
      lungeSign: 1,
    };
    this.comboIndex = index;
    this.comboTimer = 0;
    this.queued = false;
    this.charging = false;
    this.chargeTime = 0;
    this.chargeLevel = 0;
    this._attackTime = 0;
    this.game.fx.slashFlash(
      this._tmp.set(this.pos.x, 0.9, this.pos.z),
      this.facing,
      this.weapon.colors.trail,
      def.anim === 'spin' || def.anim === 'dance' ? 2.2 : 1.0,
      0.5,
    );
  }

  _beginCharge() {
    if (this.state !== 'idle') return;
    this.state = 'charge';
    this.charging = true;
    this.chargeTime = 0;
    this.chargeLevel = 0;
    this.attack = null;
    this.comboIndex = 0;
    this.comboTimer = 0;
  }

  _chargeLevelFromTime() {
    const t = this.weapon.charge.times;
    if (this.chargeTime >= t[3]) return 3;
    if (this.chargeTime >= t[2]) return 2;
    if (this.chargeTime >= t[1]) return 1;
    return 0;
  }

  _releaseCharge() {
    const lvl = Math.max(0, this._chargeLevelFromTime());
    const cd = this.weapon.charge;
    const def = {
      ...cd,
      dmg: cd.dmg[lvl],
      name: cd.name[lvl],
      isCharged: lvl,
    };
    this.charging = false;
    this.chargeTime = 0;
    this.chargeLevel = 0;
    this._startAttack(def, 0, false);
    this.game.audio.swing(this.weaponId, true);
    this.game.ui.announce(def.name.toUpperCase(), '', 1.4);
    if (lvl >= 3) this.game.shake(0.5, 0.3);
  }

  _updateCharge(dt, input) {
    if (!input.held.attack) {
      this._releaseCharge();
      return;
    }
    if (input.consume('dodge')) return; // handled above next frame
  }

  _dualSpecial() {
    if (!this.demonMode) {
      if (this.stamina < 15) { this.game.ui.hint('Not enough stamina', 1.2); return; }
      this._drainStamina(15);
      this.demonMode = true;
      this.game.audio.notify();
      this.game.ui.announce('DEMON MODE', '', 1.4);
      this.game.fx.burst(this._tmp2.set(this.pos.x, 1.0, this.pos.z), 0xb28bff, 18, 5, 1, { life: 0.7, gravity: -1 });
    } else {
      if (this.state === 'attack') { this.queuedFinisher = true; return; }
      if (this.stamina < 20) { this.game.ui.hint('Not enough stamina', 1.2); return; }
      this._drainStamina(20);
      this._startFinisher();
    }
  }

  _updateAttack(dt, monster) {
    const a = this.attack;
    if (!a) { this.state = 'idle'; return; }
    const def = a.def;
    const speedMul = (this.demonMode ? this.weapon.demon.speed : 1) * (a.finisher && this.weaponId === 'dualblades' ? 1.15 : 1);
    a.timer += dt * speedMul;
    const total = def.windup + def.active + def.recover;

    // forward lunge handled during windup/active
    if (def.lunge && (a.phase === 'windup' || a.phase === 'active')) {
      const forward = new THREE.Vector3(Math.sin(this.facing), 0, Math.cos(this.facing));
      this._move(forward.x * def.lunge * dt * 0.55, forward.z * def.lunge * dt * 0.55);
    }

    if (a.phase === 'windup' && a.timer >= def.windup) {
      a.phase = 'active';
      a.timer = 0;
      a.hitsDone = 0;
      a.tickTimer = 0;
      this.game.audio.swing(this.weaponId, !!a.finisher || !!def.isCharged);
      const flashScale = def.anim === 'spin' || def.anim === 'dance' ? 2.4 : a.finisher ? 1.8 : 1.1;
      this.game.fx.slashFlash(this._tmp.set(this.pos.x, 1.0, this.pos.z), this.facing, this.weapon.colors.trail, flashScale, 0.7);
      if (def.isCharged >= 2) this.game.shake(0.35, 0.18);
    } else if (a.phase === 'active') {
      const hits = def.hits || 1;
      if (def.hits) {
        a.tickTimer -= dt;
        if (a.tickTimer <= 0 && a.hitsDone < def.hits) {
          this._checkHit(monster, def, a);
          a.hitsDone++;
          a.tickTimer = def.hitInterval || (def.active / def.hits);
        }
      } else if (a.hitsDone === 0) {
        this._checkHit(monster, def, a);
        a.hitsDone = 1;
      }
      if (this.demonMode && this.weaponId === 'dualblades' && a.index === 2 && !a.flurryDone && a.hitsDone >= 1 && !a.finisher) {
        a.flurryDone = true;
        const fl = this.weapon.demon.flurry;
        for (let i = 0; i < fl.hits; i++) {
          setTimeout(() => {
            if (this.state === 'attack' || this.state === 'idle') {
              this._checkHit(monster, { ...def, dmg: fl.dmg, reach: def.reach }, { index: a.index, finisher: false });
            }
          }, 90 + i * 95);
        }
      }
      if (a.timer >= def.active) {
        a.phase = 'recover';
        a.timer = 0;
      }
    } else if (a.phase === 'recover') {
      if (a.timer >= def.recover) {
        this._endAttack();
        return;
      }
      if (a.timer > def.recover * 0.38) {
        if (this.queuedFinisher && this.weaponId !== 'dualblades') {
          this.queuedFinisher = false;
          this.queued = false;
          this._startFinisher();
          return;
        }
        if (this.queued) {
          this.queued = false;
          if (this.weaponId === 'greatsword' && this.game.input?.held.attack) {
            this._beginCharge();
          } else {
            this._beginCombo();
          }
          return;
        }
      }
    }
    if (a.timer > total * 2.5) this._endAttack();
  }

  _endAttack() {
    const idx = this.attack?.index ?? 0;
    this.comboIndex = idx;
    this.comboTimer = 0.65;
    this.attack = null;
    this.state = 'idle';
    if (this.weaponId === 'greatsword' && this.game.input?.held.attack) {
      this._beginCharge();
    } else if (this.game.input?.held.attack) {
      // mobile-friendly auto combo
      this._beginCombo();
    }
  }

  _checkHit(monster, def, attackInfo) {
    if (!monster || monster.dead) return;
    const parts = monster.getParts();
    const fx = this.game.fx;
    const reach = def.reach || 2.5;
    const arc = def.arc || 2.0;
    const targets = [];
    for (const part of parts) {
      if (part.broken && part.id !== 'body' && Math.random() < 0.25) continue;
      const wp = part.obj.getWorldPosition(new THREE.Vector3());
      const dx = wp.x - this.pos.x;
      const dz = wp.z - this.pos.z;
      const dist = Math.hypot(dx, dz);
      if (dist > reach + part.radius) continue;
      const ang = Math.atan2(dx, dz);
      const diff = Math.abs(angleDiff(ang, this.facing));
      const partAng = Math.atan2(part.radius, Math.max(0.6, dist)) * 0.9;
      if (diff > arc / 2 + partAng) continue;
      if (wp.y > 6 || wp.y < -1) continue;
      targets.push({ part, dist, wp });
    }
    targets.sort((a, b) => a.dist - b.dist);
    const selected = targets.slice(0, 3);
    for (const t of selected) {
      const base = (typeof def.dmg === 'number' ? def.dmg : 10) * this.dmgScale * (this.demonMode ? this.weapon.demon.damage : 1);
      this.damageDealt += base;
      this.game.playerHit({
        part: t.part,
        base,
        def,
        worldPos: t.wp,
        finisher: !!attackInfo?.finisher,
        charged: !!def.isCharged,
        demon: this.demonMode,
      });
      fx.spark(t.wp, this.weapon.colors.trail, !!attackInfo?.finisher || def.isCharged >= 2);
    }
    if (!selected.length) {
      // small whiff dust at weapon range
      const fxPos = new THREE.Vector3(this.pos.x + Math.sin(this.facing) * reach * 0.7, 0.5, this.pos.z + Math.cos(this.facing) * reach * 0.7);
      fx.dust(fxPos, 2, 0x8d8168);
    }
  }

  _emitTrail() {
    const hand = this.weaponId === 'dualblades' ? (Math.floor(this.time * 14) % 2 ? this.weaponL : this.weaponR) : this.weaponR;
    const w = hand || this.weaponR;
    if (!w) return;
    const tip = w.getObjectByName('tip');
    const base = w.getObjectByName('base');
    if (!tip || !base) return;
    const tipPos = tip.getWorldPosition(this._tmp);
    const basePos = base.getWorldPosition(this._tmp2);
    this.trail.add(basePos, tipPos, 0.2);
    if (this.weaponId === 'dualblades' && this.weaponL) {
      const tip2 = this.weaponL.getObjectByName('tip');
      const base2 = this.weaponL.getObjectByName('base');
      if (tip2 && base2) this.trail.add(base2.getWorldPosition(new THREE.Vector3()), tip2.getWorldPosition(new THREE.Vector3()), 0.16);
    }
  }

  // ------------------------------------------------------------
  usePotion() {
    if (this.potions <= 0) { this.game.ui.hint('No potions left', 1.4); return; }
    if (this.hp >= this.maxHp) { this.game.ui.hint('Health is full', 1.4); return; }
    if (this.state === 'dodge' || this.state === 'dead') return;
    this.potions--;
    this.state = 'drink';
    this.potionTimer = 0;
    this.potionHealed = false;
    this.charging = false;
    this.attack = null;
    this.game.audio.potion();
    this.game.ui.subtitle('Drinking potion…', 1.0);
  }

  _updatePotion(dt) {
    this.potionTimer += dt;
    if (!this.potionHealed && this.potionTimer >= 0.7) {
      this.potionHealed = true;
      const heal = Math.min(POTION_HEAL, this.maxHp - this.hp);
      this.hp += heal;
      this.game.ui.damage(this.game.project(this._tmp.set(this.pos.x, 1.9, this.pos.z)), `+${Math.round(heal)}`, 'heal');
      this.game.audio.potion();
      this.game.fx.burst(this._tmp.set(this.pos.x, 1.2, this.pos.z), 0x8fe36f, 14, 2.4, 1, { life: 0.8, gravity: -2 });
    }
    if (this.potionTimer >= 1.25) {
      this.state = 'idle';
    }
  }

  // ------------------------------------------------------------
  _startDodge(moveVec, moving) {
    this._drainStamina(20);
    this.state = 'dodge';
    this.dodgeTimer = 0;
    this.charging = false;
    this.attack = null;
    this.comboIndex = 0;
    this.comboTimer = 0;
    if (moving) {
      this.rollDir.set(moveVec.x, moveVec.z);
      this.facing = Math.atan2(moveVec.x, moveVec.z);
    } else {
      this.rollDir.set(-Math.sin(this.facing), -Math.cos(this.facing));
    }
    this.rollDir.normalize();
    this.invuln = 0.38;
    this.game.audio.dodge();
    this.game.fx.dust(this._tmp.set(this.pos.x, 0.15, this.pos.z), 7, 0x9a8d70);
  }

  _updateDodge(dt) {
    this.dodgeTimer += dt;
    const t = Math.min(1, this.dodgeTimer / 0.42);
    const sp = 9.5 * (1 - t * 0.6);
    this._move(this.rollDir.x * sp * dt, this.rollDir.y * sp * dt);
    if (t >= 1) {
      this.state = 'idle';
      this.dodgeTimer = 0;
    } else if (Math.random() < dt * 20) {
      this.game.fx.dust(this._tmp.set(this.pos.x, 0.12, this.pos.z), 1, 0x9a8d70);
    }
  }

  _autoAim() {
    const m = this.game.monster;
    if (!m || m.dead) return;
    const dx = m.pos.x - this.pos.x, dz = m.pos.z - this.pos.z;
    const dist = Math.hypot(dx, dz);
    if (dist < 1) return;
    const ang = Math.atan2(dx, dz);
    const diff = Math.abs(angleDiff(ang, this.facing));
    if (this.game.lockOn || diff < 2.0 || dist < 6) {
      this.facing = ang;
    }
  }

  // ------------------------------------------------------------
  takeDamage(amount, sourcePos, heavy = false) {
    if (this.dead) return { result: 'dead' };
    if (this.invuln > 0 || this.state === 'dodge') {
      return { result: 'dodge' };
    }
    let dmg = amount;
    let result = 'hit';
    const toSource = new THREE.Vector2(sourcePos.x - this.pos.x, sourcePos.z - this.pos.z).normalize();
    const forward = new THREE.Vector2(Math.sin(this.facing), Math.cos(this.facing));
    const facingSource = forward.dot(toSource) > 0.1;
    if (this.state === 'guard' && this.weapon.canGuard && facingSource) {
      const cost = this.weapon.blockStamina;
      if (this.stamina >= cost * 0.5) {
        dmg *= (1 - this.weapon.blockReduction);
        this._drainStamina(cost);
        result = 'block';
        this.blockFlash = 0.25;
        this.game.audio.impact(0.7, true, 0);
        this.game.fx.spark(this._tmp.set(this.pos.x + forward.x * 0.6, 1.2, this.pos.z + forward.y * 0.6), 0xffd58a, true);
        this.game.shake(0.15, 0.1);
        if (this.stamina <= 0) {
          result = 'guardbreak';
          this.staggerTimer = 0.8;
          this.state = 'idle';
          this.game.ui.announce('GUARD BROKEN', 'tired', 1.2);
          dmg = amount;
        }
      } else {
        result = 'guardbreak';
        this.staggerTimer = 0.8;
        this.state = 'idle';
      }
    }
    this.hp = Math.max(0, this.hp - dmg);
    this.hurtTimer = 0.3;
    if (dmg > 6) this.staggerTimer = Math.max(this.staggerTimer, heavy ? 0.5 : 0.22);
    this.invuln = 0.65;
    this.charging = false;
    this.attack = null;
    if (this.state !== 'guard') this.state = 'idle';
    if (this.potionTimer > 0) this.potionTimer = 0;
    this.game.ui.damage(this.game.project(this._tmp.set(this.pos.x, 1.9, this.pos.z)), `-${Math.round(dmg)}`, 'small');
    const away = new THREE.Vector3(this.pos.x - sourcePos.x, 0, this.pos.z - sourcePos.z).normalize();
    this.knock.addScaledVector(away, heavy ? 7 : 4.5);
    this.game.ui.flash('hurt');
    this.game.shake(heavy ? 0.5 : 0.28, heavy ? 0.3 : 0.18);
    this.game.audio.impact(0.9, false, 0);
    if (this.hp <= 0) {
      this.dead = true;
      this.state = 'dead';
      this.game.onPlayerDeath();
    }
    return { result, dmg };
  }

  // ------------------------------------------------------------
  _poseReset() {
    this.model.rotation.set(0, 0, 0);
    this.model.position.set(0, 0, 0);
    this.hips.position.y = 0.92 + 0;
    this.hips.rotation.set(0, 0, 0);
    this.torso.rotation.set(0, 0, 0);
    this.head.rotation.set(0, 0, 0);
    this.armL.rotation.set(0, 0, 0);
    this.armR.rotation.set(0, 0, 0);
    this.legL.rotation.set(0, 0, 0);
    this.legR.rotation.set(0, 0, 0);
    if (this.cape) this.cape.rotation.set(0, 0, 0);
  }

  _animate(dt, input, camera, monster) {
    if (!this.rigInit) { this._poseReset(); this.rigInit = true; }
    const pose = {
      hipY: 0, torsoX: 0, torsoY: 0, headX: 0,
      armRx: -0.08, armRy: 0, armRz: 0.12,
      armLx: -0.08, armLy: 0, armLz: -0.12,
      legLx: 0, legRx: 0,
      modelRotY: 0, modelRotX: 0,
      wRx: 0.42, wRy: 0, wRz: -0.12,
      wLx: 0, wLy: -1.15, wLz: 0.2,
      capeSwing: 0,
    };
    if (this.weaponId === 'dualblades') { pose.wRx = 1.35; pose.wRy = 0.1; pose.wRz = 0.15; pose.wLx = 1.35; pose.wLy = -0.1; pose.wLz = -0.15; }
    if (this.weaponId === 'swordshield') { pose.wRx = 0.45; pose.wRy = 0; pose.wRz = -0.05; }

    const moving = this.speedSmooth > 0.6;
    const moveAmt = clamp(this.speedSmooth / this.weapon.moveSpeed, 0, 1.2);
    if (moving) this.walkPhase += dt * (6.5 + this.speedSmooth * 0.7);
    const swing = Math.sin(this.walkPhase) * (0.55 + moveAmt * 0.25);
    if (moving) {
      pose.legLx = swing;
      pose.legRx = -swing;
      pose.armRx += -swing * 0.5;
      pose.armLx += swing * 0.5;
      pose.hipY = Math.abs(Math.cos(this.walkPhase)) * 0.045;
      pose.torsoX = 0.07 + moveAmt * 0.06;
      pose.capeSwing = -0.25 - moveAmt * 0.2;
    } else {
      const breath = Math.sin(this.time * 2.4) * 0.02;
      pose.hipY = breath;
      pose.armRx += breath * 0.8;
      pose.armLx -= breath * 0.5;
    }

    // potion drinking
    if (this.state === 'drink') {
      const t = Math.min(1, this.potionTimer / 1.2);
      pose.armRx = -2.2 + Math.sin(t * Math.PI) * -0.15;
      pose.armRz = -0.9;
      pose.headX = -0.35 * Math.sin(t * Math.PI);
      pose.wRx = 2.0;
    }

    // guard
    if (this.state === 'guard') {
      pose.hipY = -0.12;
      pose.torsoX = 0.18;
      pose.armRx = -1.25;
      pose.armRz = 0.32;
      pose.armLx = -1.35;
      pose.armLz = -0.4;
      pose.wRx = 1.1;
      if (this.weaponId === 'swordshield') {
        pose.armLx = -1.5; pose.armLz = -0.35; pose.armRx = -0.6;
        if (this.weaponL) pose.wLy = -1.5;
      }
      if (this.weaponId === 'greatsword') {
        pose.wRx = 1.55; pose.armRx = -1.5; pose.armRz = 0.25;
      }
      if (this.blockFlash > 0) { this.blockFlash -= dt; pose.torsoX -= 0.15; }
    }

    // dodge
    if (this.state === 'dodge') {
      const t = Math.min(1, this.dodgeTimer / 0.42);
      pose.hipY = -0.35 * Math.sin(t * Math.PI);
      pose.torsoX = 0.65 * Math.sin(t * Math.PI);
      pose.armLx = -1.5; pose.armRx = -1.2;
      pose.legLx = 1.1 * Math.sin(t * Math.PI); pose.legRx = -0.6;
      pose.modelRotY = -t * Math.PI * 2;
    }

    // charging
    if (this.charging) {
      pose.hipY = -0.1;
      pose.torsoX = -0.15;
      pose.torsoY = 0.65;
      pose.armRx = -2.1;
      pose.armRz = 0.4;
      pose.wRx = 1.1;
      pose.headX = 0.1;
    }

    // attack poses
    if (this.state === 'attack' && this.attack) {
      this._attackPose(pose, dt);
    }

    // hurt / stagger
    if (this.hurtTimer > 0) {
      pose.torsoX -= 0.3 * (this.hurtTimer / 0.3);
      pose.headX -= 0.2;
    }
    if (this.staggerTimer > 0 && this.state !== 'dodge') {
      pose.hipY -= 0.1;
      pose.torsoX += 0.25;
    }

    // dead
    if (this.dead) {
      pose.modelRotX = -Math.PI * 0.48;
      pose.hipY = -0.55;
      pose.modelRotY = 0;
      pose.armRx = 0.6; pose.armLx = 0.5;
      pose.legLx = 0.2; pose.legRx = -0.2;
    }

    // apply smoothly
    const k = 1 - Math.exp(-dt * 18);
    const apply = (obj, key, target) => { obj.rotation[key] = lerp(obj.rotation[key], target, k); };
    apply(this.torso, 'x', pose.torsoX);
    apply(this.torso, 'y', pose.torsoY);
    apply(this.head, 'x', pose.headX);
    apply(this.armR, 'x', pose.armRx);
    apply(this.armR, 'y', pose.armRy);
    apply(this.armR, 'z', pose.armRz);
    apply(this.armL, 'x', pose.armLx);
    apply(this.armL, 'y', pose.armLy);
    apply(this.armL, 'z', pose.armLz);
    apply(this.legL, 'x', pose.legLx);
    apply(this.legR, 'x', pose.legRx);
    this.hips.position.y = lerp(this.hips.position.y, 0.92 + pose.hipY, k);
    this.model.rotation.y = lerp(this.model.rotation.y, pose.modelRotY, 1 - Math.exp(-dt * 20));
    this.model.rotation.x = lerp(this.model.rotation.x, pose.modelRotX, this.dead ? 1 - Math.exp(-dt * 6) : k);
    if (this.cape) {
      apply(this.cape, 'x', pose.capeSwing + Math.sin(this.time * 3) * 0.05);
      apply(this.cape, 'z', Math.sin(this.time * 1.7) * 0.06);
    }
    if (this.weaponR) {
      this.weaponR.rotation.x = lerp(this.weaponR.rotation.x, pose.wRx, 1 - Math.exp(-dt * 22));
      this.weaponR.rotation.y = lerp(this.weaponR.rotation.y, pose.wRy, 1 - Math.exp(-dt * 22));
      this.weaponR.rotation.z = lerp(this.weaponR.rotation.z, pose.wRz, 1 - Math.exp(-dt * 22));
    }
    if (this.weaponL) {
      this.weaponL.rotation.x = lerp(this.weaponL.rotation.x, pose.wLx, 1 - Math.exp(-dt * 22));
      this.weaponL.rotation.y = lerp(this.weaponL.rotation.y, pose.wLy, 1 - Math.exp(-dt * 22));
      this.weaponL.rotation.z = lerp(this.weaponL.rotation.z, pose.wLz, 1 - Math.exp(-dt * 22));
    }
    this.root.rotation.y = this.facing;
    this.root.position.set(this.pos.x, 0, this.pos.z);
  }

  _attackPose(pose, dt) {
    const a = this.attack;
    const def = a.def;
    let t = 0;
    let phase = a.phase;
    if (phase === 'windup') t = clamp(a.timer / def.windup, 0, 1);
    else if (phase === 'active') t = clamp(a.timer / def.active, 0, 1);
    else t = clamp(a.timer / def.recover, 0, 1);
    const w = phase === 'windup' ? easeOut(t) : phase === 'active' ? easeInOut(t) : t;
    const anim = def.anim;

    if (anim === 'vertical' || anim === 'uppercut') {
      if (phase === 'windup') {
        pose.torsoY = 0.3 * w;
        pose.armRx = -0.3 - 2.1 * w;
        pose.armRz = 0.5;
        pose.wRx = 0.5 - 0.7 * w;
        pose.hipY = 0.02;
      } else if (phase === 'active') {
        pose.torsoY = 0.3 - 0.5 * w;
        pose.torsoX = 0.2 * w;
        pose.armRx = -2.4 + 3.4 * w;
        pose.armRz = 0.4 - 0.6 * w;
        pose.wRx = -0.2 + 1.7 * w;
        pose.hipY = -0.06 * w;
      } else {
        pose.torsoY = -0.2 * (1 - w);
        pose.armRx = 1.0 - 1.0 * w;
        pose.armRz = 0.2;
        pose.wRx = 1.5 - 1.1 * w;
      }
    } else if (anim === 'horizontal' || anim === 'spin') {
      if (anim === 'spin') {
        pose.armRx = -1.2;
        pose.armRz = -1.1;
        pose.wRx = 1.5;
        if (phase === 'windup') pose.torsoY = -0.7 * w;
        else if (phase === 'active') pose.modelRotY = -Math.PI * 2 * w;
        else pose.modelRotY = -Math.PI * 2;
        pose.hipY = -0.05;
      } else {
        if (phase === 'windup') {
          pose.torsoY = 1.1 * w;
          pose.armRx = -1.2;
          pose.armRz = -0.7;
          pose.wRx = 1.2;
          pose.hipY = -0.04;
        } else if (phase === 'active') {
          pose.torsoY = 1.1 - 2.3 * w;
          pose.armRx = -1.3;
          pose.armRz = -0.5;
          pose.wRx = 1.45;
          pose.hipY = -0.05;
        } else {
          pose.torsoY = -1.2 + 1.2 * w;
          pose.armRx = -1.0;
          pose.armRz = -0.2;
          pose.wRx = 1.35;
        }
      }
    } else if (anim === 'thrust' || anim === 'bash') {
      const forward = anim === 'bash' ? 1 : 1;
      if (phase === 'windup') {
        pose.torsoX = -0.15;
        pose.armRx = anim === 'bash' ? -1.4 : -1.3;
        pose.armRz = 0.5;
        pose.wRx = 1.4;
        pose.hipY = -0.08;
        if (anim === 'bash') { pose.armLx = -1.2; pose.armLz = -0.6; }
      } else if (phase === 'active') {
        pose.torsoX = 0.2;
        pose.armRx = -1.7;
        pose.armRz = 0.1;
        pose.wRx = 1.6;
        if (anim === 'bash') { pose.armLx = -2.1 * forward; pose.armLz = -0.45; }
      } else {
        pose.armRx = -0.6;
        pose.armRz = 0.2;
        pose.wRx = 0.8;
      }
    } else if (anim === 'dbl1' || anim === 'dbl2' || anim === 'dbl3' || anim === 'dance') {
      const speed = a.finisher ? 22 : 15;
      const spin = Math.sin(a.timer * speed);
      if (anim === 'dbl1') {
        pose.armRx = phase === 'windup' ? -1.4 : 0.8 * spin;
        pose.armRz = 0.5;
        pose.armLx = phase === 'active' ? -1.6 : -0.4;
        pose.armLz = -0.35;
        pose.torsoY = spin * 0.4;
        pose.modelRotY = phase === 'active' ? spin * 0.25 : 0;
      } else if (anim === 'dbl2') {
        pose.armLx = phase === 'windup' ? -1.4 : 0.8 * -spin;
        pose.armLz = -0.5;
        pose.armRx = phase === 'active' ? -1.6 : -0.4;
        pose.armRz = 0.35;
        pose.torsoY = -spin * 0.5;
      } else if (anim === 'dbl3') {
        pose.armRx = phase === 'windup' ? -2.0 : 1.1 * spin;
        pose.armLx = phase === 'windup' ? -2.0 : 1.1 * -spin;
        pose.armRz = 0.45; pose.armLz = -0.45;
        pose.hipY = -0.06;
      } else {
        // blade dance
        pose.armRx = -1.2 + Math.sin(a.timer * 28) * 1.3;
        pose.armLx = -1.2 + Math.cos(a.timer * 28) * 1.3;
        pose.armRz = 0.6; pose.armLz = -0.6;
        pose.torsoY = Math.sin(a.timer * 18) * 0.4;
        pose.modelRotY = -a.timer * 13;
        pose.hipY = -0.08;
      }
    } else if (anim === 'sn1' || anim === 'sn2' || anim === 'sn3') {
      if (anim === 'sn1') {
        pose.armRx = phase === 'windup' ? -1.2 : phase === 'active' ? 0.8 : 0.2;
        pose.armRz = 0.3;
        pose.torsoY = phase === 'active' ? 0.5 : 0.1;
        pose.wRx = 1.3;
      } else if (anim === 'sn2') {
        pose.armRx = -1.0;
        pose.armRz = -0.6;
        pose.wRx = 1.45;
        pose.torsoY = phase === 'active' ? -0.55 : 0;
      } else {
        pose.armRx = phase === 'windup' ? -0.8 : -1.7;
        pose.armRz = 0.18;
        pose.wRx = 1.6;
        pose.torsoX = phase === 'active' ? 0.35 : 0;
        pose.armLx = -0.9;
      }
    }
  }

  destroy() {
    this.trail?.dispose();
    this.scene.remove(this.root);
    this.root.traverse((o) => {
      if (o.geometry) o.geometry.dispose();
      if (o.material) {
        if (Array.isArray(o.material)) o.material.forEach((m) => m.dispose());
        else o.material.dispose();
      }
    });
  }
}

